INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('continent-1', 'continent', 'Africa is the second largest continent in the world by area.', '按面积计算,非洲是世界第二大洲。', 'continent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hemisphere-1', 'hemisphere', 'Summer in one hemisphere occurs at the same time as winter in the other.', '一个半球的夏季与另一个半球的冬季同时出现。', 'hemisphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equator-1', 'equator', 'Temperatures near the equator remain high throughout most of the year.', '赤道附近的气温全年大部分时间都很高。', 'equator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('latitude-1', 'latitude', 'Temperatures generally fall as latitude increases, although mountains can alter this pattern.', '气温通常随纬度升高而下降,不过山脉可能改变这一规律。', 'latitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('longitude-1', 'longitude', 'Accurate clocks allowed sailors to calculate their longitude while at sea.', '精确的时钟让水手能够在海上计算所处的经度。', 'longitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('altitude-1', 'altitude', 'Breathing becomes more difficult at high altitude because the air is thin.', '在高海拔地区,空气稀薄,呼吸变得更困难。', 'altitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elevation-1', 'elevation', 'This type of pine tree grows only at an elevation above two thousand metres.', '这种松树只生长在海拔两千米以上的地方。', 'elevation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terrain-1', 'terrain', 'The rocky terrain made it very difficult to build roads through the region.', '岩石嶙峋的地形使这一地区很难修路。', 'terrain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('landscape-1', 'landscape', 'Ice sheets shaped much of the landscape of northern Europe.', '冰盖塑造了北欧的大部分地貌。', 'landscape');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('topography-1', 'topography', 'The topography of the area affects where rain falls and rivers flow.', '这一地区的地形影响着降雨的位置和河流的走向。', 'topography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plain-1', 'plain', 'Huge herds of animals once moved across the open plains of North America.', '曾有大群动物在北美开阔的平原上迁徙。', 'plains');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plain-2', 'plain', 'It is plain from the records that the river has changed course several times.', '从记录中可以清楚地看出,这条河曾多次改道。', 'plain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('valley-1', 'valley', 'Early farmers settled in the valley because the soil there was rich.', '早期农民定居在这个山谷,因为那里土壤肥沃。', 'valley');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('canyon-1', 'canyon', 'Over millions of years, the river cut a deep canyon through the rock.', '数百万年间,这条河在岩石中切割出一道深深的大峡谷。', 'canyon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gorge-1', 'gorge', 'The road follows a narrow gorge between two high walls of rock.', '这条路沿着两面高耸岩壁之间的狭窄峡谷延伸。', 'gorge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cliff-1', 'cliff', 'Thousands of sea birds nest on the cliffs along this coast.', '数千只海鸟在这段海岸的悬崖上筑巢。', 'cliffs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slope-1', 'slope', 'Tea grows well on the steep slopes of the mountains in this region.', '茶树在这一地区陡峭的山坡上长得很好。', 'slopes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ridge-1', 'ridge', 'A long ridge of hills separates the wet coast from the dry interior.', '一道绵长的山脊把潮湿的海岸和干燥的内陆隔开。', 'ridge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('summit-1', 'summit', 'The climbers reached the summit of the mountain just after sunrise.', '登山者在日出后不久到达了山顶。', 'summit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('summit-2', 'summit', 'World leaders met at a summit to discuss the reduction of carbon emissions.', '世界各国领导人在峰会上讨论减少碳排放的问题。', 'summit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volcano-1', 'volcano', 'The volcano last erupted about four hundred years ago.', '这座火山最后一次喷发是在大约四百年前。', 'volcano');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crater-1', 'crater', 'The lake was formed when rain filled the crater of an old volcano.', '雨水注满一座古火山的火山口,形成了这个湖。', 'crater');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lava-1', 'lava', 'Hot lava flowed down the mountain and destroyed several small villages.', '炽热的熔岩从山上流下,摧毁了几个小村庄。', 'lava');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magma-1', 'magma', 'Volcanoes form when magma rises through cracks in the Earth''s surface.', '岩浆穿过地表裂缝上升时就形成了火山。', 'magma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eruption-1', 'eruption', 'Ash from the eruption blocked out the sun for several days.', '喷发产生的火山灰遮蔽了太阳好几天。', 'eruption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('earthquake-1', 'earthquake', 'The earthquake damaged most of the older buildings in the city centre.', '这场地震损坏了市中心的大部分老建筑。', 'earthquake');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seismic-1', 'seismic', 'Seismic activity in the area has increased over the past few months.', '过去几个月,该地区的地震活动有所增加。', 'Seismic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tectonic-plate-1', 'tectonic-plate', 'Mountains often form where one tectonic plate pushes against another.', '山脉常常在一个构造板块挤压另一个板块的地方形成。', 'tectonic plate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crust-1', 'crust', 'The Earth''s crust is thinnest beneath the oceans.', '地壳在海洋下面最薄。', 'crust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mantle-1', 'mantle', 'Heat from the mantle slowly moves the plates on the Earth''s surface.', '来自地幔的热量缓慢推动地球表面的板块移动。', 'mantle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('core-1', 'core', 'Scientists believe that the Earth''s core is made mainly of iron.', '科学家认为地核主要由铁构成。', 'core');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('core-2', 'core', 'Trust lies at the core of any healthy community.', '信任是任何健康社区的核心。', 'core');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fault-1', 'fault', 'Most of the region''s earthquakes occur along a major fault in the rock.', '该地区的大多数地震发生在岩石中的一条主要断层沿线。', 'fault');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('glacier-1', 'glacier', 'The glacier has moved back by more than a kilometre since 1950.', '自 1950 年以来,这条冰川已经后退了一公里多。', 'glacier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('iceberg-1', 'iceberg', 'Most of an iceberg''s mass lies hidden beneath the surface of the water.', '冰山的大部分质量隐藏在水面以下。', 'iceberg');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ice-sheet-1', 'ice-sheet', 'If the ice sheet melted completely, sea levels would rise dramatically.', '如果冰盖完全融化,海平面将急剧上升。', 'ice sheet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('polar-1', 'polar', 'Polar bears depend on sea ice for hunting seals.', '北极熊依靠海冰来捕猎海豹。', 'Polar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arctic-1', 'arctic', 'The Arctic is warming faster than almost any other part of the world.', '北极变暖的速度几乎比世界其他任何地方都快。', 'Arctic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antarctic-1', 'antarctic', 'Few plants can survive in the freezing Antarctic climate.', '很少有植物能在严寒的南极气候中存活。', 'Antarctic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tundra-1', 'tundra', 'Only small plants and mosses can grow on the frozen tundra.', '冰冻的苔原上只能生长矮小的植物和苔藓。', 'tundra');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('desert-1', 'desert', 'The desert receives less than ten centimetres of rain each year.', '这片沙漠每年的降雨量不到十厘米。', 'desert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dune-1', 'dune', 'Strong winds cause the sand dunes to move slowly across the land.', '强风使沙丘在地面上缓慢移动。', 'dunes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oasis-1', 'oasis', 'Travellers crossing the desert stopped at the oasis for water and shade.', '穿越沙漠的旅行者在绿洲停下来取水和乘凉。', 'oasis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('savanna-1', 'savanna', 'Large herds of grazing animals move across the savanna in search of fresh grass.', '大群食草动物穿越热带草原,寻找新鲜的青草。', 'savanna');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prairie-1', 'prairie', 'Much of the original prairie has now been turned into wheat fields.', '大部分原始草原如今已变成麦田。', 'prairie');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grassland-1', 'grassland', 'Overgrazing has turned large areas of grassland into dry, bare ground.', '过度放牧使大片草原变成了干燥裸露的土地。', 'grassland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rainforest-1', 'rainforest', 'The rainforest is home to millions of species of plants and insects.', '雨林是数百万种植物和昆虫的家园。', 'rainforest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wetland-1', 'wetland', 'Wetlands act as natural filters that clean water before it reaches the sea.', '湿地就像天然过滤器,在水流入海洋前将其净化。', 'Wetlands');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marsh-1', 'marsh', 'Reeds and tall grasses grow thickly in the marsh beside the river.', '河边的沼泽里长满了芦苇和高草。', 'marsh');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swamp-1', 'swamp', 'Crocodiles and many kinds of snakes live in the swamp.', '沼泽里生活着鳄鱼和多种蛇。', 'swamp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delta-1', 'delta', 'The river deposits rich soil as it reaches the delta.', '河流到达三角洲时沉积下肥沃的土壤。', 'delta');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('estuary-1', 'estuary', 'Salt water and fresh water mix in the estuary of the river.', '咸水和淡水在河口交汇。', 'estuary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('basin-1', 'basin', 'The Amazon basin contains the largest rainforest on the planet.', '亚马孙流域拥有地球上最大的雨林。', 'basin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tributary-1', 'tributary', 'Several small tributaries join the main river before it reaches the plain.', '几条小支流在到达平原之前汇入干流。', 'tributaries');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reservoir-1', 'reservoir', 'The reservoir supplies drinking water to more than a million people.', '这座水库为一百多万人提供饮用水。', 'reservoir');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('waterfall-1', 'waterfall', 'The waterfall drops nearly a hundred metres into the valley below.', '瀑布落差近一百米,直泻下方的山谷。', 'waterfall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spring-1', 'spring', 'Local people have drawn fresh water from this spring for centuries.', '几个世纪以来,当地人一直从这眼泉取用淡水。', 'spring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peninsula-1', 'peninsula', 'The peninsula is surrounded by the sea on three sides.', '这个半岛三面环海。', 'peninsula');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('archipelago-1', 'archipelago', 'The archipelago consists of more than a thousand small islands.', '这个群岛由一千多个小岛组成。', 'archipelago');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coastline-1', 'coastline', 'Rising seas are slowly changing the shape of the country''s coastline.', '不断上升的海平面正慢慢改变该国海岸线的形状。', 'coastline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shore-1', 'shore', 'Many turtles return to the same shore each year to lay their eggs.', '许多海龟每年回到同一片海岸产卵。', 'shore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bay-1', 'bay', 'Ships shelter in the bay when storms come in from the ocean.', '海上风暴来袭时,船只在海湾里避风。', 'bay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gulf-1', 'gulf', 'The oil spill spread across a large part of the gulf.', '石油泄漏扩散到了这片海湾的大部分区域。', 'gulf');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gulf-2', 'gulf', 'There is a wide gulf between the rich and the poor in the region.', '该地区贫富之间存在巨大的鸿沟。', 'gulf');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strait-1', 'strait', 'Thousands of ships pass through this narrow strait each year.', '每年有数千艘船只通过这条狭窄的海峡。', 'strait');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cave-1', 'cave', 'Paintings found in the cave are more than thirty thousand years old.', '在这个洞穴里发现的壁画已有三万多年历史。', 'cave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sediment-1', 'sediment', 'Over time, layers of sediment collect at the bottom of the lake.', '随着时间推移,一层层沉积物堆积在湖底。', 'sediment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sedimentary-1', 'sedimentary', 'Fossils are most commonly found in sedimentary rocks such as limestone.', '化石最常见于石灰岩等沉积岩中。', 'sedimentary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('erosion-1', 'erosion', 'Tree roots help to prevent soil erosion on steep hillsides.', '树根有助于防止陡峭山坡上的水土流失。', 'erosion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('erode-1', 'erode', 'Waves continue to erode the cliffs at a rate of one metre a year.', '海浪持续侵蚀悬崖,速度为每年一米。', 'erode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weathering-1', 'weathering', 'Weathering by wind and rain slowly breaks down even the hardest rock.', '风雨的风化作用能慢慢分解最坚硬的岩石。', 'Weathering');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mineral-1', 'mineral', 'Plants take up water and minerals from the soil through their roots.', '植物通过根部从土壤中吸收水分和矿物质。', 'minerals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ore-1', 'ore', 'The iron ore is transported by train to the port for export.', '铁矿石用火车运到港口出口。', 'ore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('granite-1', 'granite', 'Granite is a very hard rock that was often used for building.', '花岗岩是一种非常坚硬的岩石,常被用于建筑。', 'Granite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('limestone-1', 'limestone', 'Rainwater slowly dissolves limestone, creating large underground caves.', '雨水慢慢溶解石灰岩,形成巨大的地下洞穴。', 'limestone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sandstone-1', 'sandstone', 'The red cliffs are made of sandstone laid down millions of years ago.', '这些红色悬崖由数百万年前沉积的砂岩构成。', 'sandstone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fossil-1', 'fossil', 'The fossil of a large sea animal was found high in the mountains.', '在高山上发现了一种大型海洋动物的化石。', 'fossil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('geology-1', 'geology', 'Students of geology spend a lot of time looking closely at rocks.', '学习地质学的学生要花很多时间仔细观察岩石。', 'geology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('geography-1', 'geography', 'The geography of the island has shaped its culture and its economy.', '这座岛的地理环境塑造了它的文化和经济。', 'geography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('region-1', 'region', 'This region of the country produces most of its wine.', '该国这一地区出产该国大部分葡萄酒。', 'region');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('horizon-1', 'horizon', 'Sailors watched the land slowly disappear below the horizon.', '水手们看着陆地慢慢消失在地平线下。', 'horizon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contour-1', 'contour', 'The contour lines on the map show how steeply the land rises.', '从地图上的等高线可以看出地势升得有多陡。', 'contour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('highland-1', 'highland', 'Sheep farming has long been the main activity in the highland areas.', '长期以来,养羊一直是高地地区的主要活动。', 'highland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lowland-1', 'lowland', 'Rice grows best in lowland areas that flood during the wet season.', '水稻最适合生长在雨季会被淹没的低地。', 'lowland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meadow-1', 'meadow', 'Wild flowers cover the mountain meadows in early summer.', '初夏时节,野花开满了高山草地。', 'meadows');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jungle-1', 'jungle', 'The ruins of the ancient city were hidden in the jungle for centuries.', '这座古城的遗迹在丛林中隐藏了几个世纪。', 'jungle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scenery-1', 'scenery', 'The region''s beautiful scenery attracts thousands of walkers each summer.', '该地区美丽的风景每年夏天吸引数千名徒步者。', 'scenery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spectacle-1', 'spectacle', 'The migration of the birds across the lake is an amazing spectacle.', '鸟群飞越湖面的迁徙是一幅令人惊叹的壮观景象。', 'spectacle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cavern-1', 'cavern', 'The underground river opens into a huge cavern filled with stone columns.', '这条地下河通向一个布满石柱的巨大洞穴。', 'cavern');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crevice-1', 'crevice', 'Small lizards hide in the crevices between the rocks during the day.', '小蜥蜴白天躲在岩石之间的裂缝里。', 'crevices');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chasm-1', 'chasm', 'The earthquake opened a deep chasm across the floor of the valley.', '地震在山谷底部撕开了一道深深的裂口。', 'chasm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ledge-1', 'ledge', 'The birds lay their eggs on a narrow ledge high on the cliff.', '这些鸟把蛋产在悬崖高处狭窄的岩架上。', 'ledge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('terrestrial-1', 'terrestrial', 'Whales evolved from terrestrial animals that returned to the sea.', '鲸是由重返海洋的陆地动物进化而来的。', 'terrestrial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subterranean-1', 'subterranean', 'Blind fish live in the dark waters of these subterranean lakes.', '失明的鱼生活在这些地下湖的黑暗水域中。', 'subterranean');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('groundwater-1', 'groundwater', 'Farmers are pumping groundwater faster than it can be replaced by rain.', '农民抽取地下水的速度超过了雨水补充的速度。', 'groundwater');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offshore-1', 'offshore', 'Offshore wind farms can produce more power than those built on land.', '近海风电场的发电量可能超过陆上风电场。', 'Offshore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('islet-1', 'islet', 'Seals rest on a small rocky islet just off the coast.', '海豹在离岸不远的一个多岩石的小岛上休息。', 'islet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insular-1', 'insular', 'The island''s insular position protected it from many of the mainland''s diseases.', '这座岛的海岛位置使它免受大陆上许多疾病的侵袭。', 'insular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tropics-1', 'tropics', 'Many diseases spread by insects are common in the tropics.', '许多由昆虫传播的疾病在热带地区很常见。', 'tropics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meridian-1', 'meridian', 'The meridian passing through Greenwich marks zero degrees of longitude.', '穿过格林尼治的子午线标志着零度经线。', 'meridian');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alpine-1', 'alpine', 'Alpine plants have adapted to cold temperatures and strong winds.', '高山植物已适应低温和强风。', 'Alpine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('avalanche-1', 'avalanche', 'Heavy snowfall increases the risk of an avalanche on steep mountain slopes.', '大雪增加了陡峭山坡上发生雪崩的风险。', 'avalanche');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crevasse-1', 'crevasse', 'The climbers used ladders to cross a deep crevasse in the glacier.', '登山者用梯子越过冰川上一道深深的冰隙。', 'crevasse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stratum-1', 'stratum', 'Each stratum of rock contains clues about conditions at a particular time.', '每一层岩层都包含着某一时期环境的线索。', 'stratum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('layer-1', 'layer', 'A thick layer of ash covered the town after the volcano erupted.', '火山喷发后,厚厚一层火山灰覆盖了小镇。', 'layer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lithosphere-1', 'lithosphere', 'The lithosphere is broken into large plates that move very slowly.', '岩石圈分裂成几大板块,这些板块移动得非常缓慢。', 'lithosphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('formation-1', 'formation', 'The formation of these rocks took place over millions of years.', '这些岩石的形成历经数百万年。', 'formation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tremor-1', 'tremor', 'Local people felt a slight tremor several hours before the main earthquake.', '主震发生前几小时,当地人感觉到了轻微的震动。', 'tremor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magnitude-1', 'magnitude', 'An earthquake of this magnitude can destroy buildings within seconds.', '这种震级的地震能在几秒钟内摧毁建筑物。', 'magnitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seismology-1', 'seismology', 'Advances in seismology have made it easier to locate the centre of an earthquake.', '地震学的进步使确定地震中心变得更容易。', 'seismology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volcanic-1', 'volcanic', 'Volcanic soils are often very rich and good for growing crops.', '火山土壤往往非常肥沃,适合种植庄稼。', 'Volcanic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('erupt-1', 'erupt', 'Scientists cannot say exactly when the volcano will erupt again.', '科学家无法确切地说出这座火山何时会再次喷发。', 'erupt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thermal-1', 'thermal', 'Iceland uses thermal energy from under the ground to heat many of its homes.', '冰岛利用地下热能为许多家庭供暖。', 'thermal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quartz-1', 'quartz', 'Quartz is one of the most common minerals found in the Earth''s crust.', '石英是地壳中最常见的矿物之一。', 'Quartz');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marble-1', 'marble', 'The ancient Greeks used white marble for many of their finest buildings.', '古希腊人用白色大理石建造了许多最精美的建筑。', 'marble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gem-1', 'gem', 'Traders carried gems and spices along the old routes through the mountains.', '商人们带着宝石和香料,沿着穿越山脉的古道前行。', 'gems');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('northern-hemisphere-1', 'northern-hemisphere', 'Most of the world''s land lies in the northern hemisphere.', '世界上大部分陆地位于北半球。', 'northern hemisphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('southern-hemisphere-1', 'southern-hemisphere', 'Birds from Europe spend the winter months in the southern hemisphere.', '来自欧洲的鸟在南半球度过冬季。', 'southern hemisphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arctic-circle-1', 'arctic-circle', 'The sun does not set for weeks in the summer above the Arctic Circle.', '夏季,北极圈以北的太阳数周不落。', 'Arctic Circle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gradient-1', 'gradient', 'The railway could not be built on such a steep gradient.', '这么陡的坡度上无法修建铁路。', 'gradient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('watershed-1', 'watershed', 'The mountains form a watershed between rivers flowing east and those flowing west.', '这些山脉构成了东流河与西流河之间的分水岭。', 'watershed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('watershed-2', 'watershed', 'The invention of the steam engine was a watershed in human history.', '蒸汽机的发明是人类历史的转折点。', 'watershed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incline-1', 'incline', 'The tracks follow a gentle incline up the side of the valley.', '铁轨沿着山谷一侧的缓坡向上延伸。', 'incline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incline-2', 'incline', 'Most experts incline to the view that the climate was the main cause.', '大多数专家倾向于认为气候是主要原因。', 'incline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uplift-1', 'uplift', 'The mountains were formed by the slow uplift of the land.', '这些山脉是由陆地的缓慢抬升形成的。', 'uplift');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inland-1', 'inland', 'Rain clouds rarely reach the dry inland areas of the continent.', '雨云很少能到达这片大陆干燥的内陆地区。', 'inland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inland-2', 'inland', 'The town now lies ten kilometres inland because the coast has moved.', '由于海岸线变化,这个小镇现在位于内陆十公里处。', 'inland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wilderness-1', 'wilderness', 'Large parts of the northern wilderness are still untouched by humans.', '北部荒野的大部分地区仍未被人类涉足。', 'wilderness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quarry-1', 'quarry', 'Stone for the cathedral was brought from a quarry about ten miles away.', '建造大教堂的石料来自约十英里外的一个采石场。', 'quarry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gravel-1', 'gravel', 'The river has left thick beds of sand and gravel across the plain.', '河流在平原上留下了厚厚的沙层和砾石层。', 'gravel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dust-1', 'dust', 'Clouds of dust from the Sahara can travel thousands of kilometres.', '来自撒哈拉的尘埃云能飘行数千公里。', 'dust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('descent-1', 'descent', 'The descent into the valley took the explorers more than two days.', '探险家们下到山谷花了两天多时间。', 'descent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('descent-2', 'descent', 'Many people in the town are of Italian descent.', '镇上许多人是意大利血统。', 'descent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cape-1', 'cape', 'Sailing around the cape was one of the most dangerous parts of the voyage.', '绕过这个海角是航程中最危险的部分之一。', 'cape');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('verge-1', 'verge', 'Rare wild flowers can sometimes be found growing on the verge of the road.', '有时能在路边发现生长着的珍稀野花。', 'verge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('climate-1', 'climate', 'The climate of the region has become much drier over the past century.', '过去一个世纪,这一地区的气候变得干燥多了。', 'climate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meteorology-1', 'meteorology', 'Advances in meteorology have made it possible to warn people about storms.', '气象学的进步使人们能够提前预警风暴。', 'meteorology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atmosphere-1', 'atmosphere', 'Carbon dioxide traps heat in the atmosphere and warms the planet.', '二氧化碳把热量困在大气中,使地球变暖。', 'atmosphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atmosphere-2', 'atmosphere', 'The old market has a lively atmosphere that attracts many visitors.', '这个老市场氛围热闹,吸引了许多游客。', 'atmosphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temperature-1', 'temperature', 'The average temperature on the island is about twenty degrees.', '这座岛的平均气温约为二十度。', 'temperature');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humidity-1', 'humidity', 'High humidity makes hot weather feel even more uncomfortable.', '高湿度让炎热的天气感觉更不舒服。', 'humidity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('humid-1', 'humid', 'The humid conditions in the forest are ideal for the growth of fungi.', '森林里潮湿闷热的环境非常适合真菌生长。', 'humid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arid-1', 'arid', 'Very few people live in the arid regions of central Australia.', '澳大利亚中部的干旱地区人烟稀少。', 'arid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tropical-1', 'tropical', 'Tropical storms cause serious damage to crops along this coast.', '热带风暴给这段海岸的庄稼造成严重损害。', 'Tropical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temperate-1', 'temperate', 'Oak and beech trees are common in temperate forests.', '橡树和山毛榉在温带森林中很常见。', 'temperate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mediterranean-1', 'mediterranean', 'Olives and grapes grow well in a Mediterranean climate with dry summers.', '橄榄和葡萄在夏季干燥的地中海气候中长得很好。', 'Mediterranean');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monsoon-1', 'monsoon', 'Farmers in the region depend on the summer monsoon for their water.', '该地区的农民依靠夏季季风带来的水。', 'monsoon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('precipitation-1', 'precipitation', 'Precipitation in the mountains falls mainly as snow in winter.', '山区的降水在冬季主要以雪的形式出现。', 'Precipitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rainfall-1', 'rainfall', 'Annual rainfall has dropped by nearly a third in the past fifty years.', '过去五十年,年降雨量下降了近三分之一。', 'rainfall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drought-1', 'drought', 'A long drought forced farmers to sell most of their cattle.', '长期干旱迫使农民卖掉了大部分牛。', 'drought');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flood-1', 'flood', 'The flood destroyed roads and bridges throughout the northern part of the country.', '洪水摧毁了该国北部各地的道路和桥梁。', 'flood');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hurricane-1', 'hurricane', 'The hurricane caused severe damage along the Atlantic coast.', '飓风在大西洋沿岸造成了严重破坏。', 'hurricane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('typhoon-1', 'typhoon', 'More than a million people were moved to safety before the typhoon arrived.', '台风来临之前,有一百多万人被转移到安全地带。', 'typhoon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cyclone-1', 'cyclone', 'The cyclone brought strong winds and heavy rain to the islands.', '气旋给这些岛屿带来了强风和暴雨。', 'cyclone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tornado-1', 'tornado', 'A tornado can destroy a house in a matter of seconds.', '龙卷风能在几秒钟内摧毁一座房子。', 'tornado');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blizzard-1', 'blizzard', 'The blizzard left many remote villages without power for several days.', '这场暴风雪使许多偏远村庄断电数日。', 'blizzard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thunderstorm-1', 'thunderstorm', 'A sudden thunderstorm can cause dangerous flooding in narrow valleys.', '突如其来的雷暴可能在狭窄的山谷中引发危险的洪水。', 'thunderstorm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lightning-1', 'lightning', 'Forest fires are sometimes started by lightning during the dry season.', '旱季时,森林火灾有时是由闪电引发的。', 'lightning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hail-1', 'hail', 'Large pieces of hail damaged the fruit crop in the valley.', '大块冰雹损坏了山谷里的水果作物。', 'hail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frost-1', 'frost', 'A late frost can kill young plants in the spring.', '春季晚霜可能冻死幼苗。', 'frost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fog-1', 'fog', 'Thick fog often covers the coast during the early morning.', '清晨时分,海岸常常被浓雾笼罩。', 'fog');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breeze-1', 'breeze', 'A cool breeze from the sea keeps the town comfortable in summer.', '夏天来自海上的凉爽微风让小镇很舒适。', 'breeze');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gust-1', 'gust', 'A sudden gust of wind can make it hard for birds to land.', '一阵突如其来的强风会让鸟难以落地。', 'gust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('current-1', 'current', 'Warm ocean currents keep the coast free of ice during winter.', '温暖的洋流使海岸在冬季不结冰。', 'currents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('current-2', 'current', 'Current methods of farming may not be able to feed the future population.', '目前的耕作方法可能无法养活未来的人口。', 'Current');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('el-nino-1', 'el-nino', 'El Niño can bring heavy rain to parts of South America.', '厄尔尼诺可能给南美部分地区带来暴雨。', 'El Niño');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('global-warming-1', 'global-warming', 'Global warming is causing many species to move towards cooler areas.', '全球变暖正使许多物种向较凉爽的地区迁移。', 'Global warming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('greenhouse-effect-1', 'greenhouse-effect', 'The greenhouse effect keeps the Earth warm enough for life to exist.', '温室效应使地球保持足够的温度,让生命得以存在。', 'greenhouse effect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ozone-layer-1', 'ozone-layer', 'The ozone layer protects life on Earth from harmful radiation from the sun.', '臭氧层保护地球上的生命免受太阳有害辐射的伤害。', 'ozone layer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-dioxide-1', 'carbon-dioxide', 'Forests absorb large amounts of carbon dioxide from the air.', '森林从空气中吸收大量二氧化碳。', 'carbon dioxide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('methane-1', 'methane', 'Cattle release large quantities of methane into the atmosphere each year.', '牛每年向大气释放大量甲烷。', 'methane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emission-1', 'emission', 'The agreement commits countries to cutting their carbon emissions by half.', '这项协议要求各国把碳排放量削减一半。', 'emissions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ice-age-1', 'ice-age', 'Sea levels were much lower during the last ice age.', '上一个冰河时代的海平面要低得多。', 'ice age');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sea-level-1', 'sea-level', 'Much of the Netherlands lies below sea level and is protected by walls.', '荷兰大部分地区低于海平面,靠堤坝保护。', 'sea level');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('climatic-1', 'climatic', 'Climatic changes may have forced early people to leave the region.', '气候变化可能迫使早期的人们离开这一地区。', 'Climatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drizzle-1', 'drizzle', 'Light drizzle falls on most days during the winter months.', '冬季大部分日子都会下毛毛雨。', 'drizzle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shower-1', 'shower', 'Spring showers help the young crops to grow strongly.', '春季阵雨有助于幼苗茁壮成长。', 'showers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('downpour-1', 'downpour', 'A sudden downpour turned the dry riverbed into a fast-moving stream.', '一场突如其来的倾盆大雨把干涸的河床变成了湍急的溪流。', 'downpour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('torrential-1', 'torrential', 'Torrential rain caused landslides that blocked the main road.', '暴雨引发滑坡,堵塞了主干道。', 'Torrential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gale-1', 'gale', 'Fishing boats stayed in port because of a severe gale at sea.', '海上刮起强烈的大风,渔船都留在了港口。', 'gale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whirlwind-1', 'whirlwind', 'A whirlwind lifted sand high into the air above the desert.', '一股旋风把沙子卷到沙漠上空。', 'whirlwind');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('haze-1', 'haze', 'A thick haze from forest fires covered the city for weeks.', '森林大火产生的浓霾笼罩了这座城市数周。', 'haze');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dew-1', 'dew', 'Some desert insects collect dew from their bodies to drink.', '一些沙漠昆虫收集身上的露水来饮用。', 'dew');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('damp-1', 'damp', 'Damp conditions in the cave caused the old paintings to fade.', '洞穴里的潮湿环境使古老的壁画褪色了。', 'Damp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chilly-1', 'chilly', 'The mountain air becomes chilly as soon as the sun goes down.', '太阳一落山,山里的空气就变得寒冷。', 'chilly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('balmy-1', 'balmy', 'The island''s balmy weather makes it a popular destination in winter.', '这座岛气候温和宜人,是冬季热门的旅游目的地。', 'balmy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('torrid-1', 'torrid', 'Few people could work outside in the torrid heat of the summer.', '在夏季的酷热中,很少有人能在户外工作。', 'torrid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('windward-1', 'windward', 'Most of the rain falls on the windward side of the mountains.', '大部分雨水落在山脉的迎风面。', 'windward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barometer-1', 'barometer', 'A falling barometer is often a sign that a storm is coming.', '气压计读数下降往往是风暴来临的征兆。', 'barometer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('troposphere-1', 'troposphere', 'Almost all of the Earth''s weather occurs in the troposphere.', '地球上几乎所有的天气现象都发生在对流层。', 'troposphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turbulent-1', 'turbulent', 'The turbulent water at the foot of the falls is too dangerous for boats.', '瀑布脚下的湍急水流对船只来说太危险了。', 'turbulent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turbulent-2', 'turbulent', 'The country went through a turbulent period after the king''s death.', '国王去世后,这个国家经历了一段动荡时期。', 'turbulent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inversion-1', 'inversion', 'A temperature inversion can trap pollution close to the ground for days.', '逆温现象可能把污染物困在近地面达数日之久。', 'inversion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aerosol-1', 'aerosol', 'Aerosols from burning coal reflect some sunlight back into space.', '燃煤产生的气溶胶把部分阳光反射回太空。', 'Aerosols');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chill-1', 'chill', 'A sudden chill in the air warned the farmers that winter was near.', '空气中突然的寒意提醒农民,冬天快到了。', 'chill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marine-1', 'marine', 'Plastic waste poses a growing danger to marine animals of all sizes.', '塑料垃圾对各种大小的海洋动物构成日益严重的威胁。', 'marine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coral-reef-1', 'coral-reef', 'The coral reef provides food and shelter for thousands of species.', '珊瑚礁为数千个物种提供食物和庇护。', 'coral reef');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plankton-1', 'plankton', 'Many whales feed on tiny plankton that float near the surface.', '许多鲸以漂浮在海面附近的微小浮游生物为食。', 'plankton');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('algae-1', 'algae', 'Warm water and pollution can cause algae to spread rapidly across the lake.', '温暖的水和污染可能导致藻类在湖面迅速蔓延。', 'algae');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seaweed-1', 'seaweed', 'In parts of Asia, seaweed has long been an important source of food.', '在亚洲部分地区,海藻长期以来一直是重要的食物来源。', 'seaweed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('whale-1', 'whale', 'The blue whale is the largest animal that has ever lived.', '蓝鲸是有史以来最大的动物。', 'whale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dolphin-1', 'dolphin', 'Dolphins use a range of sounds to communicate within their groups.', '海豚用多种声音在群体内交流。', 'Dolphins');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shark-1', 'shark', 'Although people fear them, few species of shark are dangerous to humans.', '尽管人们害怕鲨鱼,但对人类有危险的鲨鱼种类很少。', 'shark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seal-1', 'seal', 'Seals come onto the beaches here to give birth in the autumn.', '海豹秋天来到这里的海滩产崽。', 'Seals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seal-2', 'seal', 'The jars were sealed with wax to keep the food fresh.', '这些罐子用蜡密封,以保持食物新鲜。', 'sealed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jellyfish-1', 'jellyfish', 'Warmer seas have led to a large increase in the number of jellyfish.', '海水变暖导致水母数量大幅增加。', 'jellyfish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('octopus-1', 'octopus', 'An octopus can change its colour to hide from its enemies.', '章鱼能改变体色来躲避天敌。', 'octopus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('squid-1', 'squid', 'Giant squid live so deep that they are rarely seen by humans.', '巨型鱿鱼生活在极深的海域,人类很少见到。', 'squid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oyster-1', 'oyster', 'Oysters help to keep the water clean by filtering out small particles.', '牡蛎通过滤除微小颗粒来帮助保持水质清洁。', 'Oysters');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crustacean-1', 'crustacean', 'Crabs and lobsters belong to a group of animals called crustaceans.', '螃蟹和龙虾属于一类被称为甲壳动物的动物。', 'crustaceans');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shellfish-1', 'shellfish', 'Fishing for shellfish has been banned because of pollution in the bay.', '由于海湾受到污染,捕捞贝类已被禁止。', 'shellfish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tide-1', 'tide', 'Twice a day, the rising tide covers the sand and the rocks.', '每天两次,上涨的潮水淹没沙滩和岩石。', 'tide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tidal-1', 'tidal', 'Tidal power could provide a reliable source of clean electricity.', '潮汐能可以提供可靠的清洁电力来源。', 'Tidal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tsunami-1', 'tsunami', 'The tsunami was caused by a powerful earthquake under the ocean.', '这场海啸是由海底强烈地震引发的。', 'tsunami');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seabed-1', 'seabed', 'Large parts of the seabed have never been properly explored.', '大部分海床从未被好好探索过。', 'seabed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trench-1', 'trench', 'The deepest known trench in the ocean is almost eleven kilometres deep.', '已知最深的海沟深度近十一公里。', 'trench');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('salinity-1', 'salinity', 'The salinity of the sea varies with temperature and rainfall.', '海水的盐度随温度和降雨量变化。', 'salinity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overfishing-1', 'overfishing', 'Overfishing has greatly reduced the number of cod in the North Sea.', '过度捕捞使北海的鳕鱼数量大幅减少。', 'Overfishing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acidification-1', 'acidification', 'Ocean acidification makes it harder for shellfish to build their shells.', '海洋酸化使贝类更难形成外壳。', 'acidification');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('submarine-1', 'submarine', 'Scientists used a small submarine to study life on the ocean floor.', '科学家用一艘小型潜艇研究海底生物。', 'submarine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sonar-1', 'sonar', 'Ships use sonar to measure the depth of the water beneath them.', '船只用声呐测量船下的水深。', 'sonar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('starfish-1', 'starfish', 'A starfish can grow a new arm if one is damaged.', '海星的腕受损后能再长出一条新的。', 'starfish');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('porpoise-1', 'porpoise', 'The porpoise is smaller than most dolphins and has a shorter nose.', '鼠海豚比大多数海豚小,吻部也更短。', 'porpoise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prawn-1', 'prawn', 'Coastal forests have been cleared to make way for prawn farms.', '沿海森林被砍伐,为对虾养殖场腾出空间。', 'prawn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shrimp-1', 'shrimp', 'Tiny shrimp are an important part of the diet of many whales.', '小虾是许多鲸鱼食物的重要组成部分。', 'shrimp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lobster-1', 'lobster', 'A lobster sheds its hard shell several times as it grows larger.', '龙虾在长大过程中会多次蜕去坚硬的外壳。', 'lobster');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crab-1', 'crab', 'The crab carries its eggs under its body until they are ready to hatch.', '螃蟹把卵带在身体下面,直到它们快要孵化。', 'crab');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clam-1', 'clam', 'A giant clam can live for more than a hundred years.', '巨蛤可以活一百多年。', 'clam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mussel-1', 'mussel', 'Mussels attach themselves firmly to rocks to avoid being washed away.', '贻贝牢牢附着在岩石上,以免被冲走。', 'Mussels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sponge-1', 'sponge', 'A sponge feeds by drawing water through small holes in its body.', '海绵通过身上的小孔吸水来获取食物。', 'sponge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coral-1', 'coral', 'Rising temperatures have caused large areas of coral to turn white and die.', '气温上升导致大片珊瑚变白死亡。', 'coral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pearl-1', 'pearl', 'A pearl forms when an oyster covers a small object with layers of shell.', '牡蛎用一层层贝壳物质包裹小物体时,就形成了珍珠。', 'pearl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ebb-1', 'ebb', 'Boats can leave the harbour only when the tide begins to ebb.', '只有潮水开始退去时,船只才能离开港口。', 'ebb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nautical-1', 'nautical', 'Portuguese sailors produced some of the most accurate nautical charts of the time.', '葡萄牙水手绘制了当时最精确的一些航海图。', 'nautical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seaport-1', 'seaport', 'The town grew rapidly into an important seaport during the 1700s.', '18 世纪,这座城镇迅速发展成重要的海港。', 'seaport');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drift-1', 'drift', 'Over millions of years, the continents have slowly drifted apart.', '数百万年间,各大洲慢慢漂移分开。', 'drifted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shallow-1', 'shallow', 'Young fish stay in shallow water where they are safer from predators.', '幼鱼待在浅水区,那里更不容易受到捕食者的攻击。', 'shallow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('species-1', 'species', 'More than two hundred species of bird have been recorded on the island.', '这座岛上已记录到两百多种鸟类。', 'species');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('organism-1', 'organism', 'Tiny organisms in the soil help to break down dead plants.', '土壤中的微小生物体有助于分解枯死的植物。', 'organisms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('creature-1', 'creature', 'Many deep-sea creatures produce their own light in the dark water.', '许多深海生物在黑暗的水中自己发光。', 'creatures');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mammal-1', 'mammal', 'Bats are the only mammals capable of true flight.', '蝙蝠是唯一能够真正飞行的哺乳动物。', 'mammals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reptile-1', 'reptile', 'Most reptiles lay eggs and rely on the sun to keep them warm.', '大多数爬行动物产卵,并依靠阳光保持体温。', 'reptiles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amphibian-1', 'amphibian', 'Frogs and other amphibians are very sensitive to pollution in the water.', '青蛙和其他两栖动物对水污染非常敏感。', 'amphibians');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('primate-1', 'primate', 'Humans share many social behaviours with other primates, such as chimpanzees.', '人类与黑猩猩等其他灵长类动物有许多相同的社会行为。', 'primates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rodent-1', 'rodent', 'Rats and other rodents can spread disease through their waste.', '老鼠和其他啮齿动物可以通过排泄物传播疾病。', 'rodents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marsupial-1', 'marsupial', 'A marsupial carries its young in a pouch on the front of its body.', '有袋动物把幼崽放在身体前部的育儿袋中。', 'marsupial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vertebrate-1', 'vertebrate', 'Fish were the first vertebrates to appear on Earth.', '鱼类是地球上最早出现的脊椎动物。', 'vertebrates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invertebrate-1', 'invertebrate', 'Invertebrates such as worms and insects make up most animal species.', '蠕虫和昆虫等无脊椎动物占动物物种的大多数。', 'Invertebrates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insect-1', 'insect', 'Without insects to carry pollen, many plants could not reproduce.', '如果没有昆虫传粉,许多植物将无法繁殖。', 'insects');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beetle-1', 'beetle', 'Some species of beetle can damage entire forests within a few years.', '某些种类的甲虫能在几年内毁掉整片森林。', 'beetle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('butterfly-1', 'butterfly', 'The butterfly travels thousands of kilometres from Canada to Mexico each autumn.', '这种蝴蝶每年秋天从加拿大飞越数千公里到达墨西哥。', 'butterfly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moth-1', 'moth', 'Unlike butterflies, most moths are active during the night.', '与蝴蝶不同,大多数飞蛾在夜间活动。', 'moths');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mosquito-1', 'mosquito', 'Only the female mosquito bites people, as it needs blood for its eggs.', '只有雌蚊才叮人,因为它需要血液来产卵。', 'mosquito');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('termite-1', 'termite', 'Termites build huge nests that stay at a constant temperature.', '白蚁建造巨大的巢穴,巢内温度保持恒定。', 'Termites');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spider-1', 'spider', 'Most spiders catch their food in webs made of very strong silk.', '大多数蜘蛛用极其坚韧的丝织成的网捕捉食物。', 'spiders');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parasite-1', 'parasite', 'The parasite lives inside the fish and slowly weakens it.', '这种寄生虫生活在鱼体内,使它慢慢变得虚弱。', 'parasite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predator-1', 'predator', 'Sharp eyesight helps the bird to escape from its main predators.', '敏锐的视力帮助这种鸟逃避主要的捕食者。', 'predators');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prey-1', 'prey', 'Owls can locate their prey by sound alone, even in total darkness.', '即使在完全黑暗中,猫头鹰也能仅凭声音确定猎物的位置。', 'prey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prey-2', 'prey', 'These large cats prey mainly on deer and wild pigs.', '这些大型猫科动物主要捕食鹿和野猪。', 'prey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carnivore-1', 'carnivore', 'Lions and other large carnivores need very large areas in which to hunt.', '狮子和其他大型食肉动物需要很大的狩猎范围。', 'carnivores');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('herbivore-1', 'herbivore', 'Elephants are herbivores that eat up to 150 kilos of plants a day.', '大象是食草动物,每天吃多达 150 公斤的植物。', 'herbivores');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('omnivore-1', 'omnivore', 'As an omnivore, the bear eats both meat and a wide range of plants.', '作为杂食动物,熊既吃肉,也吃各种植物。', 'omnivore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scavenger-1', 'scavenger', 'Vultures are scavengers that feed on animals already dead.', '秃鹫是以已死动物为食的食腐动物。', 'scavengers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('herd-1', 'herd', 'A herd of elephants can travel long distances in search of water.', '一群大象可以长途跋涉寻找水源。', 'herd');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flock-1', 'flock', 'A large flock of geese flies over the valley every autumn.', '每年秋天都有一大群大雁飞越这个山谷。', 'flock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swarm-1', 'swarm', 'A swarm of locusts can destroy a whole field of crops in hours.', '一群蝗虫能在几小时内毁掉整片庄稼。', 'swarm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('colony-1', 'colony', 'Ants live in a large colony with a single queen.', '蚂蚁生活在只有一只蚁后的大群体中。', 'colony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('colony-2', 'colony', 'The British established their first colony in North America in the 1600s.', '英国人在 17 世纪在北美建立了第一个殖民地。', 'colony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nest-1', 'nest', 'Both parents help to build the nest and feed the young birds.', '父母双方都帮忙筑巢和喂养幼鸟。', 'nest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burrow-1', 'burrow', 'Rabbits live in an underground burrow that protects them from predators.', '兔子住在地下洞穴里,可以躲避捕食者。', 'burrow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burrow-2', 'burrow', 'Some animals burrow deep into the sand to escape the desert heat.', '有些动物深挖沙洞来躲避沙漠的炎热。', 'burrow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hive-1', 'hive', 'Bees return to the hive and use a special dance to share information.', '蜜蜂回到蜂巢后,用一种特殊的舞蹈传递信息。', 'hive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('den-1', 'den', 'The female bear gives birth in a den during the winter months.', '母熊在冬季的兽穴中产崽。', 'den');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('habitat-1', 'habitat', 'The destruction of its forest habitat has put the animal at great risk.', '森林栖息地遭到破坏,使这种动物面临巨大风险。', 'habitat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ecosystem-1', 'ecosystem', 'The loss of a single species can affect the entire ecosystem.', '一个物种的消失可能影响整个生态系统。', 'ecosystem');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ecology-1', 'ecology', 'She studied the ecology of the river before the dam was built.', '她在大坝建成之前研究了这条河的生态。', 'ecology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biodiversity-1', 'biodiversity', 'Tropical forests have the highest level of biodiversity on land.', '热带森林拥有陆地上最高的生物多样性。', 'biodiversity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('food-chain-1', 'food-chain', 'Chemicals become more concentrated as they move up the food chain.', '化学物质沿食物链向上传递时,浓度会越来越高。', 'food chain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('food-web-1', 'food-web', 'Removing one animal from a food web can have unexpected effects.', '从食物网中移除一种动物可能产生意想不到的影响。', 'food web');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('niche-1', 'niche', 'Each species in the forest occupies its own ecological niche.', '森林中的每个物种都占据着自己的生态位。', 'niche');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('symbiosis-1', 'symbiosis', 'Corals live in symbiosis with tiny plants that provide them with food.', '珊瑚与为其提供食物的微小植物共生。', 'symbiosis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mutualism-1', 'mutualism', 'Mutualism occurs when two species both benefit from living closely together.', '当两个物种紧密生活在一起并都受益时,就形成了互利共生。', 'Mutualism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('camouflage-1', 'camouflage', 'The insect''s green colour provides excellent camouflage among the leaves.', '这种昆虫的绿色在树叶间提供了极好的伪装。', 'camouflage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mimicry-1', 'mimicry', 'Mimicry allows some harmless snakes to look like dangerous ones.', '拟态使一些无害的蛇看起来像危险的蛇。', 'Mimicry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('instinct-1', 'instinct', 'Young turtles move towards the sea by instinct as soon as they hatch.', '小海龟一孵化出来,就凭本能爬向大海。', 'instinct');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('behaviour-1', 'behaviour', 'Researchers filmed the animals to study their behaviour in the wild.', '研究者拍摄这些动物,以研究它们在野外的行为。', 'behaviour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('territory-1', 'territory', 'Male birds sing loudly to defend their territory against rivals.', '雄鸟大声鸣叫,保卫领地不受对手侵犯。', 'territory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('migrate-1', 'migrate', 'Many birds migrate south to avoid the cold winter months.', '许多鸟南迁以躲避寒冷的冬季。', 'migrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('migration-1', 'migration', 'The long migration of these birds takes them across the Sahara Desert.', '这些鸟的长途迁徙要飞越撒哈拉沙漠。', 'migration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hibernate-1', 'hibernate', 'Some bears hibernate for up to seven months in very cold regions.', '在非常寒冷的地区,有些熊冬眠长达七个月。', 'hibernate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hibernation-1', 'hibernation', 'During hibernation, the animal''s heart rate drops to a fraction of its normal level.', '冬眠期间,这种动物的心率会远低于正常水平。', 'hibernation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breed-1', 'breed', 'Sea birds return to these islands each year to breed.', '海鸟每年回到这些岛屿繁殖。', 'breed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breed-2', 'breed', 'Farmers developed this breed of sheep for its soft wool.', '农民培育这种羊的品种是为了获取柔软的羊毛。', 'breed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reproduce-1', 'reproduce', 'Some plants can reproduce without producing any seeds at all.', '有些植物完全不产生种子也能繁殖。', 'reproduce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reproduction-1', 'reproduction', 'Warm temperatures are needed for the successful reproduction of many reptiles.', '许多爬行动物要在温暖的气温下才能成功繁殖。', 'reproduction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mate-1', 'mate', 'Male peacocks display their bright feathers to attract a mate.', '雄孔雀展示鲜艳的羽毛来吸引配偶。', 'mate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mate-2', 'mate', 'Some birds mate for life and return to the same nest each year.', '有些鸟终生配对,每年回到同一个巢。', 'mate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('offspring-1', 'offspring', 'Sea turtles do not care for their offspring after laying their eggs.', '海龟产卵后不照顾后代。', 'offspring');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('larva-1', 'larva', 'The larva feeds on leaves until it is ready to change into an adult.', '幼虫以树叶为食,直到准备好变为成虫。', 'larva');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hatch-1', 'hatch', 'The eggs hatch after about three weeks, depending on the temperature.', '根据温度不同,这些蛋大约三周后孵化。', 'hatch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embryo-1', 'embryo', 'The embryo develops inside the egg for about twenty days.', '胚胎在蛋内发育约二十天。', 'embryo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evolution-1', 'evolution', 'Darwin''s theory of evolution changed the way people viewed the natural world.', '达尔文的进化论改变了人们看待自然界的方式。', 'evolution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('natural-selection-1', 'natural-selection', 'Through natural selection, the fish developed colours that matched the sea floor.', '通过自然选择,这些鱼进化出了与海底相近的颜色。', 'natural selection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adaptation-1', 'adaptation', 'Thick fur is an adaptation that allows the animal to survive severe cold.', '厚皮毛是一种适应,使这种动物能够在严寒中生存。', 'adaptation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gene-1', 'gene', 'A single gene may determine the colour of the bird''s feathers.', '单个基因可能决定这种鸟的羽毛颜色。', 'gene');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genetic-1', 'genetic', 'Genetic tests show that the two populations separated about a million years ago.', '基因检测显示,这两个种群大约在一百万年前分开。', 'Genetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mutation-1', 'mutation', 'A random mutation may give an animal a small advantage over others.', '随机突变可能让某只动物比其他个体略占优势。', 'mutation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inherit-1', 'inherit', 'Children inherit half of their genes from each parent.', '孩子从父母双方各继承一半的基因。', 'inherit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trait-1', 'trait', 'Long necks are a useful trait for animals feeding on tall trees.', '对于以高大树木为食的动物来说,长脖子是一种有用的特征。', 'trait');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ancestor-1', 'ancestor', 'Modern horses evolved from a much smaller ancestor that lived in forests.', '现代马是从一种生活在森林中、体型小得多的祖先进化而来的。', 'ancestor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('descendant-1', 'descendant', 'Today''s dogs are all descendants of the grey wolf.', '如今的狗都是灰狼的后裔。', 'descendants');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extinct-1', 'extinct', 'The dodo became extinct within a century of the arrival of humans.', '人类到来后不到一个世纪,渡渡鸟就灭绝了。', 'extinct');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extinction-1', 'extinction', 'Hundreds of plants are now in danger of extinction due to habitat loss.', '由于栖息地丧失,现在有数百种植物面临灭绝的危险。', 'extinction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endangered-1', 'endangered', 'The law protects endangered animals and the places where they live.', '法律保护濒危动物及其栖息之地。', 'endangered');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('threatened-1', 'threatened', 'Many threatened birds have begun to recover since hunting was banned.', '自禁猎以来,许多受威胁的鸟类已开始恢复。', 'threatened');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('poaching-1', 'poaching', 'Poaching remains a serious problem for elephants in parts of Africa.', '在非洲部分地区,偷猎仍然是大象面临的严重问题。', 'Poaching');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conservation-1', 'conservation', 'Conservation groups are working to protect the last areas of old forest.', '保护组织正在努力保护最后的原始森林区。', 'Conservation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sanctuary-1', 'sanctuary', 'The bird sanctuary provides a safe place for thousands of migrating geese.', '这个鸟类保护区为数千只迁徙的大雁提供了安全的地方。', 'sanctuary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('captivity-1', 'captivity', 'The pandas bred in captivity will later be released into the wild.', '这些圈养繁殖的大熊猫之后将被放归野外。', 'captivity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('domesticate-1', 'domesticate', 'People began to domesticate sheep and goats around ten thousand years ago.', '人类大约一万年前开始驯化绵羊和山羊。', 'domesticate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wildlife-1', 'wildlife', 'The national park is famous for its rich and varied wildlife.', '这个国家公园以丰富多样的野生动物闻名。', 'wildlife');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fauna-1', 'fauna', 'The island''s fauna includes several species found nowhere else.', '这座岛的动物群中有几种在其他地方都找不到的物种。', 'fauna');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flora-1', 'flora', 'The local flora changes greatly as you climb higher up the mountain.', '随着海拔升高,当地的植物群变化很大。', 'flora');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('feather-1', 'feather', 'Scientists have found dinosaur fossils with clear signs of feathers.', '科学家发现了带有明显羽毛痕迹的恐龙化石。', 'feathers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beak-1', 'beak', 'The shape of a bird''s beak depends on the kind of food it eats.', '鸟喙的形状取决于它吃的食物种类。', 'beak');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('claw-1', 'claw', 'The animal uses its sharp claws to dig for insects under the ground.', '这种动物用锋利的爪子在地下挖昆虫。', 'claws');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fin-1', 'fin', 'Fish use their fins to steer and to balance in the water.', '鱼用鳍在水中控制方向和保持平衡。', 'fins');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gill-1', 'gill', 'Fish take oxygen from the water through their gills.', '鱼通过鳃从水中获取氧气。', 'gills');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scale-1', 'scale', 'The snake''s skin is covered with small, dry scales.', '蛇的皮肤上覆盖着干燥的小鳞片。', 'scales');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scale-2', 'scale', 'The scale of the damage only became clear several weeks later.', '损失的规模几周后才变得清晰。', 'scale');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tusk-1', 'tusk', 'Elephants use their tusks to dig for water and to strip bark from trees.', '大象用长牙挖水和剥树皮。', 'tusks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('horn-1', 'horn', 'Both male and female animals of this species have long curved horns.', '这个物种的雄性和雌性都长有弯曲的长角。', 'horns');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fur-1', 'fur', 'The animal''s thick fur protects it from temperatures far below zero.', '这种动物厚厚的皮毛使它能抵御远低于零度的低温。', 'fur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antenna-1', 'antenna', 'Insects use each antenna to touch and smell things around them.', '昆虫用每根触角触碰和嗅闻周围的东西。', 'antenna');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('venom-1', 'venom', 'Snake venom is now used in the development of some medicines.', '蛇毒现在被用于开发一些药物。', 'venom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('venomous-1', 'venomous', 'Only a small number of the country''s snakes are venomous.', '该国只有少数蛇是有毒的。', 'venomous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dinosaur-1', 'dinosaur', 'The dinosaur fossils were found in rocks about seventy million years old.', '这些恐龙化石是在约七千万年前的岩石中发现的。', 'dinosaur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ape-1', 'ape', 'Chimpanzees and other apes are able to use simple tools.', '黑猩猩和其他猿类能够使用简单的工具。', 'apes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gorilla-1', 'gorilla', 'A gorilla family usually consists of one adult male, several females and their young.', '一个大猩猩家庭通常由一只成年雄性、几只雌性和幼崽组成。', 'gorilla');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chimpanzee-1', 'chimpanzee', 'A chimpanzee can learn to use a stick to catch insects.', '黑猩猩能学会用树枝捕捉昆虫。', 'chimpanzee');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('baboon-1', 'baboon', 'Baboons live in large groups with a strict order of rank.', '狒狒生活在有严格等级的大群体中。', 'Baboons');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rhinoceros-1', 'rhinoceros', 'The rhinoceros has been hunted almost to extinction for its horn.', '犀牛因其角遭到捕杀,几近灭绝。', 'rhinoceros');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hippopotamus-1', 'hippopotamus', 'The hippopotamus spends most of the day in water to keep cool.', '河马白天大部分时间待在水中以保持凉爽。', 'hippopotamus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crocodile-1', 'crocodile', 'The female crocodile carries her newly hatched young to the water in her mouth.', '雌鳄鱼用嘴把刚孵化的幼崽衔到水里。', 'crocodile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('leopard-1', 'leopard', 'The leopard often drags its food up into a tree for safety.', '豹常把食物拖到树上以保安全。', 'leopard');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kangaroo-1', 'kangaroo', 'A young kangaroo stays in its mother''s pouch for about six months.', '小袋鼠在母亲的育儿袋中待大约六个月。', 'kangaroo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('koala-1', 'koala', 'The koala feeds almost entirely on the leaves of eucalyptus trees.', '考拉几乎完全以桉树叶为食。', 'koala');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('otter-1', 'otter', 'The otter uses stones as tools to open shellfish.', '水獭用石头作工具打开贝类。', 'otter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beaver-1', 'beaver', 'A beaver can build a dam that changes the flow of a whole river.', '河狸能筑起改变整条河流流向的水坝。', 'beaver');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tortoise-1', 'tortoise', 'The giant tortoise can live for well over a hundred years.', '巨型陆龟可以活一百多岁。', 'tortoise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turtle-1', 'turtle', 'Each year the turtles return to lay their eggs on this beach.', '每年海龟都回到这片海滩产卵。', 'turtles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lizard-1', 'lizard', 'Some lizards can lose their tails to escape from an attacker.', '有些蜥蜴能断尾逃脱攻击者。', 'lizards');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chameleon-1', 'chameleon', 'A chameleon can move each of its eyes in a different direction.', '变色龙的两只眼睛能分别朝不同方向转动。', 'chameleon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('toad-1', 'toad', 'Unlike frogs, a toad usually has dry skin covered in small lumps.', '与青蛙不同,蟾蜍的皮肤通常干燥,布满小疙瘩。', 'toad');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ostrich-1', 'ostrich', 'The ostrich cannot fly, but it can run at very high speed.', '鸵鸟不会飞,但能高速奔跑。', 'ostrich');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('penguin-1', 'penguin', 'Male penguins keep the eggs warm during the long Antarctic winter.', '在漫长的南极冬季,雄企鹅负责为蛋保暖。', 'penguins');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pelican-1', 'pelican', 'The pelican catches fish in the large pouch under its beak.', '鹈鹕用喙下的大囊袋捕鱼。', 'pelican');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('owl-1', 'owl', 'Soft feathers allow the owl to fly almost silently at night.', '柔软的羽毛让猫头鹰夜间飞行时几乎悄无声息。', 'owl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('woodpecker-1', 'woodpecker', 'A woodpecker uses its strong beak to search for insects under tree bark.', '啄木鸟用强壮的喙在树皮下寻找昆虫。', 'woodpecker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crane-1', 'crane', 'The crane performs an elaborate dance during the breeding season.', '鹤在繁殖季节会跳一种精心编排的舞蹈。', 'crane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crane-2', 'crane', 'A large crane lifted the sections of the bridge into position.', '一台大型起重机把桥的各部分吊到了位。', 'crane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('finch-1', 'finch', 'Darwin noticed that the beak of each finch suited its particular diet.', '达尔文注意到,每只雀的喙都适合它特定的食物。', 'finch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crow-1', 'crow', 'Crows have been seen using tools to reach food in narrow spaces.', '有人观察到乌鸦使用工具获取狭窄空间里的食物。', 'Crows');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sparrow-1', 'sparrow', 'The number of house sparrows has fallen sharply in many European cities.', '在许多欧洲城市,家麻雀的数量急剧下降。', 'sparrows');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pigeon-1', 'pigeon', 'Pigeons were once used to carry messages over long distances during wars.', '鸽子曾在战争中被用来远距离传递消息。', 'Pigeons');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fowl-1', 'fowl', 'Early farmers kept fowl for both their meat and their eggs.', '早期农民饲养家禽,既为吃肉也为取蛋。', 'fowl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('locust-1', 'locust', 'A locust can eat its own weight in food every day.', '蝗虫每天能吃下相当于自身体重的食物。', 'locust');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wasp-1', 'wasp', 'Some types of wasp lay their eggs inside the bodies of other insects.', '有些种类的黄蜂把卵产在其他昆虫体内。', 'wasp');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dragonfly-1', 'dragonfly', 'A dragonfly can fly backwards and stay still in the air.', '蜻蜓能向后飞,也能悬停在空中。', 'dragonfly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('caterpillar-1', 'caterpillar', 'The caterpillar eats large amounts of leaves before forming a hard case.', '毛毛虫吃下大量树叶后,才形成坚硬的外壳。', 'caterpillar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('silkworm-1', 'silkworm', 'The Chinese kept the secret of the silkworm for many centuries.', '中国人把蚕的秘密保守了许多个世纪。', 'silkworm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('earthworm-1', 'earthworm', 'Earthworms improve the soil by creating small tunnels through the ground.', '蚯蚓在地下钻出小隧道,从而改良土壤。', 'Earthworms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('worm-1', 'worm', 'Birds use their sharp eyesight to find a worm in the grass.', '鸟用敏锐的视力在草丛中寻找蠕虫。', 'worm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mollusc-1', 'mollusc', 'Snails and octopuses both belong to the group known as molluscs.', '蜗牛和章鱼都属于软体动物这一类群。', 'molluscs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cub-1', 'cub', 'A lion cub stays with its mother for about two years.', '狮子幼崽和母亲一起生活大约两年。', 'cub');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pupa-1', 'pupa', 'The insect stays inside the pupa for about two weeks before it appears.', '这种昆虫在蛹内待大约两周才出来。', 'pupa');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carrion-1', 'carrion', 'Vultures have a strong sense of smell that helps them to find carrion.', '秃鹫嗅觉灵敏,这有助于它们找到腐肉。', 'carrion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tentacle-1', 'tentacle', 'The jellyfish catches small fish with its long tentacles.', '水母用长长的触手捕捉小鱼。', 'tentacles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spine-1', 'spine', 'The human spine supports the head and protects important nerves.', '人的脊柱支撑头部,并保护重要的神经。', 'spine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spine-2', 'spine', 'Hard spines on the plant prevent animals from eating its leaves.', '这种植物上坚硬的刺防止动物吃它的叶子。', 'spines');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hump-1', 'hump', 'A camel stores fat in its hump to use when food is scarce.', '骆驼把脂肪储存在驼峰里,供食物短缺时使用。', 'hump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hide-1', 'hide', 'Early people used animal hide to make warm clothes and shelters.', '早期的人们用兽皮制作保暖的衣物和住所。', 'hide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('webbed-1', 'webbed', 'Ducks have webbed feet that help them to swim quickly.', '鸭子有蹼足,这有助于它们快速游泳。', 'webbed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genus-1', 'genus', 'Lions and tigers belong to the same genus of large cats.', '狮子和老虎同属大型猫科动物中的一个属。', 'genus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carnivorous-1', 'carnivorous', 'Carnivorous plants obtain extra nutrients by trapping small insects.', '食肉植物通过捕捉小昆虫获取额外的养分。', 'Carnivorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('herbivorous-1', 'herbivorous', 'Herbivorous dinosaurs needed huge amounts of plants to stay alive.', '食草恐龙需要大量植物才能存活。', 'Herbivorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('omnivorous-1', 'omnivorous', 'Pigs are omnivorous and will eat almost anything they can find.', '猪是杂食的,几乎什么都吃。', 'omnivorous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('predatory-1', 'predatory', 'Some predatory fish hunt in groups to catch larger animals.', '一些捕食性鱼类成群捕猎,以捕捉较大的动物。', 'predatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nocturnal-1', 'nocturnal', 'Most bats are nocturnal and sleep in caves during the day.', '大多数蝙蝠是夜行性的,白天在洞穴里睡觉。', 'nocturnal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aquatic-1', 'aquatic', 'Many aquatic plants absorb nutrients directly from the surrounding water.', '许多水生植物直接从周围的水中吸收养分。', 'aquatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gregarious-1', 'gregarious', 'These gregarious birds nest close together in very large groups.', '这些群居的鸟聚集成很大的群体,紧挨着筑巢。', 'gregarious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monogamous-1', 'monogamous', 'Only a small number of mammals are thought to be monogamous.', '人们认为只有少数哺乳动物是一夫一妻的。', 'monogamous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endemic-1', 'endemic', 'Many of the plants on the islands are endemic and grow nowhere else.', '岛上的许多植物是当地特有的,在其他地方都不生长。', 'endemic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endemic-2', 'endemic', 'Malaria is endemic in many tropical parts of the world.', '疟疾在世界许多热带地区是地方性疾病。', 'endemic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hereditary-1', 'hereditary', 'Some forms of the disease are hereditary and pass from parent to child.', '这种疾病的某些类型是遗传的,由父母传给孩子。', 'hereditary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spawn-1', 'spawn', 'Salmon swim back up the same river to spawn each year.', '鲑鱼每年逆流游回同一条河产卵。', 'spawn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peck-1', 'peck', 'The young chicks peck at the shell until it breaks open.', '小鸡不停地啄蛋壳,直到把它啄破。', 'peck');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proliferate-1', 'proliferate', 'Bacteria can proliferate quickly in warm and wet conditions.', '细菌在温暖潮湿的环境中能迅速繁殖。', 'proliferate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('propagate-1', 'propagate', 'Gardeners often propagate this plant by cutting and replanting its stems.', '园丁常通过扦插茎来繁殖这种植物。', 'propagate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subsist-1', 'subsist', 'In winter, the deer subsist on bark and small branches.', '冬天,鹿靠树皮和小树枝维持生存。', 'subsist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strain-1', 'strain', 'A new strain of the virus has spread rapidly through the region.', '这种病毒的一个新品种已在该地区迅速传播。', 'strain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strain-2', 'strain', 'Rapid population growth has put a great strain on the water supply.', '人口快速增长给供水带来了巨大压力。', 'strain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secrete-1', 'secrete', 'Glands in the skin secrete a substance that protects against infection.', '皮肤中的腺体分泌一种防止感染的物质。', 'secrete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('secretion-1', 'secretion', 'The plant''s sticky secretion traps insects that land on its leaves.', '这种植物的黏性分泌物能粘住落在叶子上的昆虫。', 'secretion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assimilate-1', 'assimilate', 'Plants assimilate nitrogen from the soil through their roots.', '植物通过根部从土壤中吸收氮。', 'assimilate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assimilate-2', 'assimilate', 'Immigrants often assimilate into local society within a few generations.', '移民往往在几代之内融入当地社会。', 'assimilate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('morphology-1', 'morphology', 'The morphology of the bones suggests that the animal walked on two legs.', '骨骼的形态表明这种动物用两条腿行走。', 'morphology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('microscope-1', 'microscope', 'The invention of the microscope allowed scientists to see bacteria for the first time.', '显微镜的发明使科学家第一次看到了细菌。', 'microscope');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('darwinism-1', 'darwinism', 'Darwinism was fiercely debated by scientists and religious leaders in the 1860s.', '19 世纪 60 年代,科学家和宗教领袖就达尔文学说展开了激烈争论。', 'Darwinism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endangered-species-1', 'endangered-species', 'The tiger is an endangered species, with very few left in the wild.', '老虎是濒危物种,野外所剩无几。', 'endangered species');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('natural-habitat-1', 'natural-habitat', 'Zoos cannot fully recreate the natural habitat of these large animals.', '动物园无法完全重现这些大型动物的自然栖息地。', 'natural habitat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bird-of-prey-1', 'bird-of-prey', 'The eagle is a large bird of prey with extremely sharp eyesight.', '雕是一种视力极其敏锐的大型猛禽。', 'bird of prey');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hawk-1', 'hawk', 'A hawk circled high above the field, looking for small animals.', '一只鹰在田野上空高高盘旋,寻找小动物。', 'hawk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sniff-1', 'sniff', 'Dogs sniff the air to detect the smell of other animals.', '狗嗅空气以察觉其他动物的气味。', 'sniff');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eagle-1', 'eagle', 'The eagle builds a huge nest of sticks at the top of a tall tree.', '雕在高树顶上用树枝搭建巨大的巢。', 'eagle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cage-1', 'cage', 'Keeping large birds in a small cage can cause them great stress.', '把大型鸟类关在小笼子里会让它们承受巨大压力。', 'cage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chick-1', 'chick', 'Each chick must leave the nest within about two months of hatching.', '每只雏鸟都要在孵化后大约两个月内离巢。', 'chick');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bait-1', 'bait', 'Scientists used fish as bait to attract the sharks to their cameras.', '科学家用鱼作诱饵,把鲨鱼吸引到相机前。', 'bait');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crawl-1', 'crawl', 'Newly hatched turtles crawl across the sand towards the sea.', '刚孵化的小海龟爬过沙滩奔向大海。', 'crawl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('botany-1', 'botany', 'Her interest in botany began with the wild flowers near her home.', '她对植物学的兴趣始于家附近的野花。', 'botany');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vegetation-1', 'vegetation', 'The vegetation on the northern side of the hill is much thicker.', '山丘北侧的植被要茂密得多。', 'vegetation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shrub-1', 'shrub', 'Low shrubs are the main form of plant life in the dry hills.', '矮小的灌木是干燥山丘上主要的植物类型。', 'shrubs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bush-1', 'bush', 'Small birds often hide their nests deep inside a thick bush.', '小鸟常把巢藏在茂密灌木丛的深处。', 'bush');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vine-1', 'vine', 'The vine climbs up the trunks of tall trees to reach the light.', '藤蔓沿着高树的树干向上攀爬,以获取阳光。', 'vine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('moss-1', 'moss', 'Moss grows well on wet rocks in the shade of the forest.', '苔藓在森林树荫下的湿石上长得很好。', 'Moss');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fern-1', 'fern', 'Ferns reproduce by means of spores rather than seeds.', '蕨类通过孢子而不是种子繁殖。', 'Ferns');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fungus-1', 'fungus', 'The fungus spreads through the roots and slowly kills the tree.', '这种真菌在根部蔓延,慢慢杀死树木。', 'fungus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mushroom-1', 'mushroom', 'Some wild mushrooms are poisonous and can be fatal if eaten.', '有些野生蘑菇有毒,吃了可能致命。', 'mushrooms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seed-1', 'seed', 'Birds carry the seeds of many plants over long distances.', '鸟类把许多植物的种子带到很远的地方。', 'seeds');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('seedling-1', 'seedling', 'The young seedlings need protection from frost during their first year.', '幼苗在第一年需要防霜保护。', 'seedlings');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sprout-1', 'sprout', 'The first green leaves sprout from the seeds within a few days.', '几天之内,种子就发芽长出第一批绿叶。', 'sprout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('germinate-1', 'germinate', 'Some seeds will germinate only after they have been through a fire.', '有些种子只有经过火烧才会发芽。', 'germinate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stem-1', 'stem', 'Water travels up the stem from the roots to the leaves.', '水沿着茎从根部输送到叶子。', 'stem');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trunk-1', 'trunk', 'The age of a tree can be found by counting the rings in its trunk.', '通过数树干上的年轮可以知道树的年龄。', 'trunk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bark-1', 'bark', 'The bark of this tree was used to make medicine for fevers.', '这种树的树皮曾被用来制作退烧药。', 'bark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('twig-1', 'twig', 'Birds gather twigs and dry grass to build their nests.', '鸟收集细枝和干草来筑巢。', 'twigs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petal-1', 'petal', 'Bright petals attract insects to the centre of the flower.', '鲜艳的花瓣把昆虫吸引到花朵中心。', 'petals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollen-1', 'pollen', 'Bees carry pollen from one flower to another as they feed.', '蜜蜂采食时把花粉从一朵花带到另一朵花。', 'pollen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollinate-1', 'pollinate', 'Many fruit trees depend on bees to pollinate their flowers.', '许多果树依靠蜜蜂为花朵授粉。', 'pollinate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pollination-1', 'pollination', 'Without pollination by insects, many fruit crops would produce far less food.', '如果没有昆虫授粉,许多果树的产量会大幅减少。', 'pollination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nectar-1', 'nectar', 'Hummingbirds feed on nectar from flowers using their long, thin beaks.', '蜂鸟用又长又细的喙吸食花蜜。', 'nectar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blossom-1', 'blossom', 'Cherry blossom attracts large crowds of visitors to the park each spring.', '樱花每年春天吸引大批游客来到公园。', 'blossom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blossom-2', 'blossom', 'Apple trees blossom in spring, and the fruit is picked in autumn.', '苹果树春天开花,秋天摘果。', 'blossom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bloom-1', 'bloom', 'This rare flower blooms for just a single night each year.', '这种珍稀的花每年只开一夜。', 'blooms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('photosynthesis-1', 'photosynthesis', 'Plants use photosynthesis to turn sunlight and water into energy.', '植物通过光合作用把阳光和水转化为能量。', 'photosynthesis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chlorophyll-1', 'chlorophyll', 'Chlorophyll gives plants their green colour and absorbs energy from the sun.', '叶绿素使植物呈现绿色,并吸收太阳能量。', 'Chlorophyll');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deciduous-1', 'deciduous', 'Deciduous trees lose all of their leaves during the autumn.', '落叶树在秋季会落光所有树叶。', 'Deciduous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evergreen-1', 'evergreen', 'Evergreen trees keep their leaves throughout the entire year.', '常绿树全年都保留树叶。', 'Evergreen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conifer-1', 'conifer', 'A conifer has narrow leaves that help it to survive cold winters.', '针叶树的叶子细长,有助于它度过寒冬。', 'conifer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('timber-1', 'timber', 'Ships in the past were built almost entirely from timber.', '过去的船几乎完全用木材建造。', 'timber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lumber-1', 'lumber', 'Companies cut down trees in the northern forests to produce lumber.', '公司砍伐北部森林的树木来生产木材。', 'lumber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deforestation-1', 'deforestation', 'Deforestation has increased the risk of flooding in many tropical countries.', '森林砍伐增加了许多热带国家的洪水风险。', 'Deforestation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('afforestation-1', 'afforestation', 'Afforestation programmes aim to create new forests on empty land.', '植树造林项目旨在在荒地上营造新的森林。', 'Afforestation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('agriculture-1', 'agriculture', 'Agriculture still employs most of the population in the region.', '农业仍然雇用了该地区的大多数人口。', 'Agriculture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('agricultural-1', 'agricultural', 'New machines led to a rapid increase in agricultural production.', '新机器使农业产量迅速增长。', 'agricultural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('farming-1', 'farming', 'Farming began in this area about eight thousand years ago.', '这一地区的农业大约始于八千年前。', 'Farming');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crop-1', 'crop', 'Rice is the main crop grown in the flooded fields of the south.', '水稻是南方水田种植的主要农作物。', 'crop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crop-2', 'crop', 'A poor crop can leave small farmers with too little to eat.', '歉收可能让小农户没有足够的食物。', 'crop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cereal-1', 'cereal', 'Wheat and other cereals provide much of the world''s food.', '小麦和其他谷物提供了世界上大部分的食物。', 'cereals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grain-1', 'grain', 'Farmers store their grain in dry buildings to prevent it from rotting.', '农民把谷物储存在干燥的建筑里,防止腐烂。', 'grain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grain-2', 'grain', 'Each grain of sand on the beach was once part of a larger rock.', '海滩上的每一粒沙子都曾是一块大岩石的一部分。', 'grain');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wheat-1', 'wheat', 'Bread made from wheat became the main food in much of Europe.', '小麦做的面包成为欧洲大部分地区的主食。', 'wheat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barley-1', 'barley', 'Barley grows well in cool climates and is often used to make beer.', '大麦在凉爽气候中长得很好,常用来酿啤酒。', 'Barley');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maize-1', 'maize', 'Maize was first grown in Central America thousands of years ago.', '玉米最早于数千年前在中美洲种植。', 'Maize');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soybean-1', 'soybean', 'The soybean is grown mainly for animal feed and for cooking oil.', '大豆主要用作动物饲料和食用油原料。', 'soybean');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harvest-1', 'harvest', 'Heavy rain just before the harvest can destroy a whole year''s work.', '收获前的大雨可能毁掉一整年的劳动成果。', 'harvest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('harvest-2', 'harvest', 'Farmers usually harvest the grapes by hand in late summer.', '农民通常在夏末用手采摘葡萄。', 'harvest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plough-1', 'plough', 'The invention of the iron plough made it easier to farm heavy soil.', '铁犁的发明使耕种黏重的土壤变得更容易。', 'plough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plough-2', 'plough', 'Farmers used oxen to plough their fields before tractors were invented.', '拖拉机发明之前,农民用牛犁地。', 'plough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irrigation-1', 'irrigation', 'Irrigation has allowed crops to be grown in very dry parts of the country.', '灌溉使该国非常干旱的地区也能种植庄稼。', 'Irrigation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('irrigate-1', 'irrigate', 'Farmers use water from the river to irrigate their fields in summer.', '夏天,农民用河水灌溉田地。', 'irrigate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fertiliser-1', 'fertiliser', 'Too much fertiliser can run off the land and harm nearby rivers.', '过多的化肥会从土地上流失,危害附近的河流。', 'fertiliser');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fertile-1', 'fertile', 'The fertile soil along the river produced good crops every year.', '沿河肥沃的土壤每年都能产出好庄稼。', 'fertile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barren-1', 'barren', 'After years of overuse, the land became barren and could not be farmed.', '经过多年过度使用,这片土地变得贫瘠,无法耕种。', 'barren');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soil-1', 'soil', 'Rich soil holds both water and the nutrients that plants need.', '肥沃的土壤既能保水,也含有植物所需的养分。', 'soil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pesticide-1', 'pesticide', 'Some pesticides kill helpful insects as well as those that damage crops.', '有些农药不仅杀死危害庄稼的昆虫,也杀死益虫。', 'pesticides');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('herbicide-1', 'herbicide', 'The herbicide kills unwanted plants without harming the wheat.', '这种除草剂能杀死杂草,但不会伤害小麦。', 'herbicide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pest-1', 'pest', 'Birds help farmers by eating insect pests that damage crops.', '鸟类吃掉危害庄稼的害虫,从而帮助农民。', 'pests');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('weed-1', 'weed', 'Weeds compete with crops for sunlight, water and space.', '杂草与庄稼争夺阳光、水分和空间。', 'Weeds');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('livestock-1', 'livestock', 'Most of the land is used for raising livestock such as cows and sheep.', '大部分土地用于饲养牛羊等家畜。', 'livestock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cattle-1', 'cattle', 'Herds of cattle were once driven long distances across the plains to market.', '牛群曾被长途驱赶,穿越平原去往市场。', 'cattle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dairy-farm-1', 'dairy-farm', 'Most dairy farms in the area produce milk for local cheese makers.', '该地区的大多数奶牛场为当地奶酪生产商供奶。', 'dairy farms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ranch-1', 'ranch', 'The family owns a large cattle ranch in the south of the state.', '这家人在该州南部拥有一个大牧场。', 'ranch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('graze-1', 'graze', 'Sheep graze on the hills during the summer and return to the valley in autumn.', '羊夏天在山上吃草,秋天回到山谷。', 'graze');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pasture-1', 'pasture', 'The farmer moves the cows to fresh pasture every few days.', '农民每隔几天把牛转移到新的牧场。', 'pasture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plantation-1', 'plantation', 'Many workers on the sugar plantation lived in very poor conditions.', '糖料种植园的许多工人生活条件非常差。', 'plantation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('greenhouse-1', 'greenhouse', 'Tomatoes can be grown all year round in a heated greenhouse.', '番茄可以在加热的温室里全年种植。', 'greenhouse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genetically-modified-1', 'genetically-modified', 'Some people are worried about the safety of genetically modified food.', '有些人担心转基因食品的安全性。', 'genetically modified');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('famine-1', 'famine', 'Millions of people died during the famine that followed the failed harvest.', '歉收后的饥荒导致数百万人死亡。', 'famine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('food-security-1', 'food-security', 'Climate change poses a serious risk to food security in many countries.', '气候变化对许多国家的粮食安全构成严重风险。', 'food security');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('botanical-1', 'botanical', 'The botanical garden contains plants collected from all over the world.', '这座植物园收藏着来自世界各地的植物。', 'botanical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inorganic-1', 'inorganic', 'Plants absorb inorganic substances from the soil and turn them into food.', '植物从土壤中吸收无机物,并把它们转化为养分。', 'inorganic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foliage-1', 'foliage', 'The thick foliage of the trees hides the birds from their enemies.', '茂密的树叶把鸟藏了起来,使其不被天敌发现。', 'foliage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bud-1', 'bud', 'New buds appear on the branches as soon as the weather warms.', '天气一转暖,枝头就长出新芽。', 'buds');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shoot-1', 'shoot', 'Pandas feed mainly on the young shoots and leaves of bamboo.', '大熊猫主要以竹子的嫩枝和叶子为食。', 'shoots');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stalk-1', 'stalk', 'Corn plants have tall stalks that can reach three metres in height.', '玉米植株的茎秆很高,可达三米。', 'stalks');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bough-1', 'bough', 'The heavy snow broke a large bough from the old oak tree.', '大雪压断了老橡树上一根粗大的树枝。', 'bough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('husk-1', 'husk', 'The outer husk of the rice is removed before it is eaten.', '稻米的外壳要去掉才能食用。', 'husk');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shell-1', 'shell', 'The hard shell protects the soft body of the animal inside.', '坚硬的外壳保护着里面动物柔软的身体。', 'shell');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peel-1', 'peel', 'The peel of the fruit contains oils that keep insects away.', '这种水果的果皮含有能驱赶昆虫的油脂。', 'peel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peel-2', 'peel', 'Workers peel the bark from the trees by hand.', '工人们用手剥下树皮。', 'peel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('log-1', 'log', 'The heavy logs were floated down the river to the sawmill.', '沉重的原木顺河漂到锯木厂。', 'logs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spore-1', 'spore', 'The wind can carry each spore a long way from the parent plant.', '风能把每个孢子带到离母株很远的地方。', 'spore');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('herb-1', 'herb', 'Many traditional medicines are made from wild herbs.', '许多传统药物由野生草本植物制成。', 'herbs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reed-1', 'reed', 'Ancient Egyptians made a type of paper from a tall water reed.', '古埃及人用一种高大的水生芦苇造纸。', 'reed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orchid-1', 'orchid', 'Each type of orchid depends on a particular insect for pollination.', '每一种兰花都依赖特定的昆虫授粉。', 'orchid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cactus-1', 'cactus', 'A cactus stores water in its thick stem during long dry periods.', '仙人掌在漫长的干旱期把水分储存在粗壮的茎中。', 'cactus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sequoia-1', 'sequoia', 'The giant sequoia can grow to more than eighty metres in height.', '巨型红杉可以长到八十多米高。', 'sequoia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rubber-1', 'rubber', 'Natural rubber comes from a liquid produced by certain tropical trees.', '天然橡胶来自某些热带树木产生的液体。', 'rubber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('starch-1', 'starch', 'Potatoes are rich in starch, which provides the body with energy.', '土豆富含淀粉,能为身体提供能量。', 'starch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('glucose-1', 'glucose', 'Plants produce glucose as a source of energy during photosynthesis.', '植物在光合作用中产生葡萄糖作为能量来源。', 'glucose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fermentation-1', 'fermentation', 'Fermentation turns the sugar in grapes into alcohol.', '发酵把葡萄中的糖转化为酒精。', 'Fermentation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ripe-1', 'ripe', 'The fruit changes from green to red when it is ripe.', '这种水果成熟时由绿变红。', 'ripe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prolific-1', 'prolific', 'Rabbits are prolific breeders and can quickly take over new areas.', '兔子繁殖力极强,能迅速占领新地区。', 'prolific');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infertile-1', 'infertile', 'Much of the land is infertile and can support only a few sheep.', '大部分土地贫瘠,只能养少量的羊。', 'infertile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arable-1', 'arable', 'Only a small part of the country''s land is arable.', '该国只有一小部分土地可以耕种。', 'arable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('husbandry-1', 'husbandry', 'Good animal husbandry helps to keep farm animals healthy.', '良好的畜牧管理有助于保持家畜健康。', 'husbandry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('horticulture-1', 'horticulture', 'Students of horticulture learn how to grow fruit, vegetables and flowers.', '学习园艺的学生学习如何种植水果、蔬菜和花卉。', 'horticulture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hydroponics-1', 'hydroponics', 'Hydroponics allows vegetables to be grown in water without any soil.', '水培法使蔬菜可以在水中生长,完全不需要土壤。', 'Hydroponics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manure-1', 'manure', 'Farmers spread animal manure on the fields to improve the soil.', '农民把动物粪肥撒在田里来改良土壤。', 'manure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insecticide-1', 'insecticide', 'Spraying insecticide can also harm birds that feed on the insects.', '喷洒杀虫剂也会伤害以这些昆虫为食的鸟类。', 'insecticide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fodder-1', 'fodder', 'Farmers grow oats as fodder for their horses during the winter.', '农民种燕麦作为马冬天的饲料。', 'fodder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hay-1', 'hay', 'Dried grass is stored as hay to feed the cattle in winter.', '干草被储存起来,冬天用来喂牛。', 'hay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('granary-1', 'granary', 'The Romans built a large granary to store wheat for the city.', '罗马人建造了一座大粮仓,为城市储存小麦。', 'granary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sorghum-1', 'sorghum', 'Sorghum can grow in hot, dry areas where other cereals fail.', '高粱能在其他谷物难以生长的炎热干旱地区生长。', 'Sorghum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tractor-1', 'tractor', 'The arrival of the tractor reduced the number of farm workers needed.', '拖拉机的出现减少了所需的农场工人数量。', 'tractor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intensive-1', 'intensive', 'Intensive farming produces more food but can damage the soil.', '集约化耕作产量更高,但可能损害土壤。', 'Intensive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hedge-1', 'hedge', 'The old hedge between the fields provides a home for small birds.', '田地之间的老树篱为小鸟提供了栖身之所。', 'hedge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hedge-2', 'hedge', 'Farmers grow several different crops to hedge against the risk of bad weather.', '农民种植多种作物,以对冲恶劣天气的风险。', 'hedge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nutrient-1', 'nutrient', 'Soil loses important nutrients when the same crop is grown every year.', '每年种同一种作物,土壤就会流失重要的营养物。', 'nutrients');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phosphate-1', 'phosphate', 'Phosphate from farms can cause harmful changes in lakes and rivers.', '农场流出的磷酸盐可能对湖泊和河流造成有害影响。', 'Phosphate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('yeast-1', 'yeast', 'Yeast is added to the mixture to make the bread rise.', '在面团中加入酵母,面包才能发起来。', 'Yeast');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pine-1', 'pine', 'Tall pine forests cover the mountains in the north of the country.', '该国北部的山上覆盖着高大的松树林。', 'pine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mill-1', 'mill', 'The old flour mill on the river is now a small museum.', '河边的老面粉厂现在是一座小博物馆。', 'mill');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mill-2', 'mill', 'Thousands of people came to the city to work in the cotton mills.', '成千上万的人来到这座城市,在棉纺厂工作。', 'mills');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('palm-1', 'palm', 'Local people use the leaves of the palm to make baskets and roofs.', '当地人用棕榈叶编篮子和盖屋顶。', 'palm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forestry-1', 'forestry', 'Forestry provides many jobs in the sparsely populated north of the country.', '林业为该国人口稀少的北部提供了许多工作岗位。', 'Forestry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sow-1', 'sow', 'Farmers sow the seeds in spring, just after the last frost.', '农民在春天最后一场霜过后播种。', 'sow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reap-1', 'reap', 'Farmers who invest in better soil will reap the benefits for years.', '投资改良土壤的农民多年都能从中获益。', 'reap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shepherd-1', 'shepherd', 'A shepherd moved the sheep up into the hills every summer.', '每年夏天,牧羊人把羊赶到山上。', 'shepherd');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cart-1', 'cart', 'Vegetables were taken to market by horse and cart until the 1920s.', '直到 20 世纪 20 年代,蔬菜还靠马车运到市场。', 'cart');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physics-1', 'physics', 'The laws of physics explain why objects fall towards the ground.', '物理定律解释了物体为什么会向地面坠落。', 'physics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chemistry-1', 'chemistry', 'Knowledge of chemistry helped early metal workers to produce stronger tools.', '化学知识帮助早期的金属工匠制造出更坚固的工具。', 'chemistry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('matter-1', 'matter', 'Scientists believe that most matter in the universe cannot be seen directly.', '科学家认为,宇宙中的大部分物质无法直接观测。', 'matter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('matter-2', 'matter', 'Small differences in temperature matter a great deal to these insects.', '微小的温差对这些昆虫来说很要紧。', 'matter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('substance-1', 'substance', 'This substance becomes a liquid when it is heated above ninety degrees.', '这种物质加热到九十度以上就会变成液体。', 'substance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('particle-1', 'particle', 'Tiny particles of dust in the air can damage the lungs.', '空气中的微小尘埃颗粒会损害肺部。', 'particles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atom-1', 'atom', 'Every atom of an element contains the same number of protons.', '同一种元素的每个原子含有相同数量的质子。', 'atom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('molecule-1', 'molecule', 'A water molecule consists of two hydrogen atoms and one oxygen atom.', '一个水分子由两个氢原子和一个氧原子组成。', 'molecule');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electron-1', 'electron', 'An electron carries a negative charge and moves around the centre of an atom.', '电子带负电荷,围绕原子中心运动。', 'electron');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('proton-1', 'proton', 'A proton carries a positive charge and is found in the centre of an atom.', '质子带正电荷,位于原子中心。', 'proton');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neutron-1', 'neutron', 'A neutron has about the same mass as a proton but carries no charge.', '中子的质量与质子大致相同,但不带电荷。', 'neutron');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nucleus-1', 'nucleus', 'The nucleus contains most of the mass of an atom.', '原子核包含了原子的大部分质量。', 'nucleus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compound-1', 'compound', 'Salt is a compound made from sodium and chlorine.', '盐是由钠和氯构成的化合物。', 'compound');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mixture-1', 'mixture', 'Air is a mixture of nitrogen, oxygen and several other gases.', '空气是氮气、氧气和其他几种气体的混合物。', 'mixture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oxygen-1', 'oxygen', 'All animals need oxygen in order to produce energy.', '所有动物都需要氧气来产生能量。', 'oxygen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hydrogen-1', 'hydrogen', 'Hydrogen could become an important clean fuel for trucks and ships.', '氢可能成为卡车和船舶的重要清洁燃料。', 'Hydrogen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nitrogen-1', 'nitrogen', 'Certain plants add nitrogen to the soil and so improve its quality.', '某些植物能给土壤增加氮,从而改善土质。', 'nitrogen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-1', 'carbon', 'Trees store carbon in their wood as they grow.', '树木在生长过程中把碳储存在木材里。', 'carbon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sodium-1', 'sodium', 'Too much sodium in the diet can lead to high blood pressure.', '饮食中钠过多可能导致高血压。', 'sodium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calcium-1', 'calcium', 'Calcium is needed to build strong bones and teeth.', '强健的骨骼和牙齿需要钙。', 'Calcium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('iron-1', 'iron', 'Iron tools gradually replaced those made of softer metals.', '铁制工具逐渐取代了较软金属制成的工具。', 'Iron');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('copper-1', 'copper', 'Copper is widely used in electrical wires because it conducts electricity well.', '铜导电性好,因此被广泛用于电线。', 'Copper');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aluminium-1', 'aluminium', 'Aluminium is light and strong, so it is widely used in aircraft.', '铝又轻又坚固,所以被广泛用于飞机。', 'Aluminium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alloy-1', 'alloy', 'Steel is an alloy of iron and a small amount of carbon.', '钢是铁和少量碳的合金。', 'alloy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acid-1', 'acid', 'Strong acid can burn the skin and damage most metals.', '强酸能灼伤皮肤,并损坏大多数金属。', 'acid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alkaline-1', 'alkaline', 'Plants of this kind grow best in alkaline soil rich in lime.', '这类植物最适合生长在富含石灰的碱性土壤中。', 'alkaline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solution-1', 'solution', 'The metal dissolves slowly when it is placed in a weak acid solution.', '把这种金属放入弱酸溶液中,它会慢慢溶解。', 'solution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solution-2', 'solution', 'Recycling alone is not a complete solution to the problem of waste.', '仅靠回收并不能彻底解决废物问题。', 'solution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solvent-1', 'solvent', 'Water is an excellent solvent and can dissolve many different substances.', '水是极好的溶剂,能溶解许多不同的物质。', 'solvent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vapour-1', 'vapour', 'Water vapour in the air turns into rain when it cools.', '空气中的水蒸气冷却后变成雨。', 'vapour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evaporate-1', 'evaporate', 'Water evaporates quickly from the surface of shallow lakes in summer.', '夏天,浅湖表面的水蒸发得很快。', 'evaporates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('condense-1', 'condense', 'Warm air rises, cools and condenses to form clouds.', '暖空气上升、冷却后冷凝形成云。', 'condenses');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freeze-1', 'freeze', 'Water expands when it freezes, and this can break even solid rock.', '水结冰时会膨胀,甚至能使坚硬的岩石破裂。', 'freezes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('melt-1', 'melt', 'Rising temperatures are causing mountain glaciers to melt more quickly.', '气温上升导致山地冰川融化得更快。', 'melt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boil-1', 'boil', 'Water boils at a lower temperature at the top of a high mountain.', '在高山山顶,水的沸点较低。', 'boils');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reaction-1', 'reaction', 'The chemical reaction releases heat and produces a small amount of gas.', '这个化学反应释放热量,并产生少量气体。', 'reaction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catalyst-1', 'catalyst', 'The metal acts as a catalyst and speeds up the chemical process.', '这种金属起催化剂作用,加快了化学过程。', 'catalyst');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catalyst-2', 'catalyst', 'The invention of printing was a catalyst for great social change.', '印刷术的发明促进了巨大的社会变革。', 'catalyst');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oxidation-1', 'oxidation', 'Oxidation causes iron to rust when it is exposed to air and water.', '氧化使铁暴露在空气和水中时生锈。', 'Oxidation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('combustion-1', 'combustion', 'The combustion of coal releases large quantities of carbon dioxide.', '煤的燃烧释放大量二氧化碳。', 'combustion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('toxic-1', 'toxic', 'Some factories have released toxic waste into nearby rivers.', '一些工厂把有毒废物排入附近的河流。', 'toxic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radiation-1', 'radiation', 'Too much radiation from the sun can damage the skin.', '过多的太阳辐射会损伤皮肤。', 'radiation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radioactive-1', 'radioactive', 'Radioactive waste must be stored safely for thousands of years.', '放射性废物必须安全储存数千年。', 'Radioactive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nuclear-1', 'nuclear', 'Nuclear power produces little carbon dioxide but creates dangerous waste.', '核能产生的二氧化碳很少,但会产生危险的废物。', 'Nuclear');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('energy-1', 'energy', 'Plants store energy from the sun in the form of sugar.', '植物以糖的形式储存来自太阳的能量。', 'energy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('force-1', 'force', 'The force of the water gradually wore away the rock.', '水流的力量逐渐磨蚀了岩石。', 'force');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('force-2', 'force', 'Rising sea levels may force people to leave their homes.', '海平面上升可能迫使人们离开家园。', 'force');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('friction-1', 'friction', 'Friction between the tyres and the road slows a car down.', '轮胎和路面之间的摩擦使汽车减速。', 'Friction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pressure-1', 'pressure', 'Water pressure increases rapidly as you go deeper into the ocean.', '越往海洋深处,水压增加得越快。', 'pressure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('velocity-1', 'velocity', 'The velocity of the river increases as it flows down the steep slope.', '河水流下陡坡时,流速会增加。', 'velocity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acceleration-1', 'acceleration', 'The acceleration of an object depends on the force acting on it.', '物体的加速度取决于作用在它上面的力。', 'acceleration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('momentum-1', 'momentum', 'A heavy ship has so much momentum that it takes a long time to stop.', '大船的动量很大,需要很长时间才能停下来。', 'momentum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('momentum-2', 'momentum', 'The campaign for cleaner air has gained momentum in recent years.', '近年来,争取清洁空气的运动势头越来越强。', 'momentum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mass-1', 'mass', 'The Sun contains almost all the mass of the solar system.', '太阳几乎占了太阳系的全部质量。', 'mass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mass-2', 'mass', 'Mass production made cars affordable for ordinary families.', '大规模生产让普通家庭也买得起汽车。', 'Mass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('density-1', 'density', 'Ice floats on water because it has a lower density.', '冰能浮在水面上,是因为它的密度较低。', 'density');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magnetic-1', 'magnetic', 'Some birds use the Earth''s magnetic field to find their way.', '有些鸟利用地球磁场辨别方向。', 'magnetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magnet-1', 'magnet', 'A compass needle is a small magnet that points to the north.', '指南针的指针是一块指向北方的小磁铁。', 'magnet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electricity-1', 'electricity', 'The country produces most of its electricity from hydropower.', '这个国家的大部分电力来自水力发电。', 'electricity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electrical-1', 'electrical', 'Nerves send electrical signals from the brain to the rest of the body.', '神经把电信号从大脑传到身体其他部位。', 'electrical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circuit-1', 'circuit', 'Electricity can flow only when the circuit is complete.', '只有电路闭合时,电流才能流动。', 'circuit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('voltage-1', 'voltage', 'High voltage power lines carry electricity over long distances.', '高压输电线路进行远距离输电。', 'voltage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('battery-1', 'battery', 'Better battery technology has made electric cars far more practical.', '更好的电池技术让电动汽车实用多了。', 'battery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conductor-1', 'conductor', 'Copper is a good conductor of both heat and electricity.', '铜是热和电的良导体。', 'conductor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conductor-2', 'conductor', 'The conductor of the orchestra chose a programme of modern music.', '乐团指挥选了一组现代音乐曲目。', 'conductor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insulation-1', 'insulation', 'Good insulation keeps heat inside the building during cold winters.', '良好的隔热层能在寒冬把热量留在建筑内。', 'insulation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('frequency-1', 'frequency', 'Bats can hear sounds at a frequency too high for humans.', '蝙蝠能听到人类听不到的高频率声音。', 'frequency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wavelength-1', 'wavelength', 'Red light has a longer wavelength than blue light.', '红光的波长比蓝光长。', 'wavelength');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spectrum-1', 'spectrum', 'Rainbows show the full spectrum of colours found in sunlight.', '彩虹展现了阳光中完整的色彩光谱。', 'spectrum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infrared-1', 'infrared', 'Infrared cameras can detect animals by the heat of their bodies.', '红外线相机能通过动物的体温探测到它们。', 'Infrared');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ultraviolet-1', 'ultraviolet', 'Ultraviolet light from the sun can cause skin cancer.', '来自太阳的紫外线可能导致皮肤癌。', 'Ultraviolet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('laser-1', 'laser', 'Surgeons now use a laser to correct many common eye problems.', '外科医生现在用激光矫正许多常见的眼部问题。', 'laser');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optical-1', 'optical', 'Optical fibres carry information around the world at very high speed.', '光纤以极高的速度在全球传输信息。', 'Optical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lens-1', 'lens', 'A lens at the front of the eye focuses light onto the retina.', '眼睛前部的晶状体把光聚焦到视网膜上。', 'lens');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reflect-1', 'reflect', 'Snow and ice reflect most of the sunlight back into space.', '冰雪把大部分阳光反射回太空。', 'reflect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reflect-2', 'reflect', 'The results reflect a general decline in the level of reading.', '这些结果反映出阅读水平的普遍下降。', 'reflect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('refract-1', 'refract', 'Water droplets refract sunlight, and that is how a rainbow forms.', '水滴折射阳光,彩虹就是这样形成的。', 'refract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('absorb-1', 'absorb', 'Dark surfaces absorb more heat than light-coloured surfaces.', '深色表面比浅色表面吸收更多热量。', 'absorb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emit-1', 'emit', 'Power stations emit large amounts of carbon dioxide into the air.', '发电站向空气中排放大量二氧化碳。', 'emit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fossil-fuel-1', 'fossil-fuel', 'Burning fossil fuels is the main source of greenhouse gases.', '燃烧化石燃料是温室气体的主要来源。', 'fossil fuels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coal-1', 'coal', 'Coal was the main source of energy during the Industrial Revolution.', '煤炭是工业革命时期的主要能源。', 'Coal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petroleum-1', 'petroleum', 'Plastic and many other everyday materials are made from petroleum.', '塑料和许多其他日常材料都是由石油制成的。', 'petroleum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crude-oil-1', 'crude-oil', 'The price of crude oil rose sharply during the 1970s.', '20 世纪 70 年代,原油价格急剧上涨。', 'crude oil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('natural-gas-1', 'natural-gas', 'Natural gas produces less carbon dioxide than coal when burned.', '天然气燃烧时产生的二氧化碳比煤少。', 'Natural gas');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('renewable-1', 'renewable', 'Renewable sources now provide a third of the country''s electricity.', '可再生能源现在提供该国三分之一的电力。', 'Renewable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solar-panel-1', 'solar-panel', 'Many homes now have a solar panel on the roof to reduce their bills.', '现在许多家庭在屋顶安装太阳能电池板来减少电费。', 'solar panel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wind-turbine-1', 'wind-turbine', 'A single wind turbine can supply power to hundreds of homes.', '一台风力涡轮机能为数百户家庭供电。', 'wind turbine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hydroelectric-1', 'hydroelectric', 'The hydroelectric dam provides most of the power used in the valley.', '这座水力发电站大坝提供了山谷大部分的用电。', 'hydroelectric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('geothermal-1', 'geothermal', 'Geothermal plants use heat from deep underground to produce electricity.', '地热电站利用地下深处的热量发电。', 'Geothermal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biofuel-1', 'biofuel', 'Biofuel made from food crops may push up the price of food.', '用粮食作物制成的生物燃料可能推高粮价。', 'Biofuel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('generator-1', 'generator', 'A small generator provides power for the village when the main supply fails.', '主电源中断时,一台小型发电机为村庄供电。', 'generator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('power-station-1', 'power-station', 'The old power station burned coal brought in by train.', '这座旧发电站燃烧由火车运来的煤。', 'power station');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grid-1', 'grid', 'Electricity from the wind farm is fed into the national grid.', '风电场发出的电被输入国家电网。', 'grid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ion-1', 'ion', 'An ion is an atom that has gained or lost an electron.', '离子是得到或失去电子的原子。', 'ion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atomic-1', 'atomic', 'Atomic clocks can measure time with extraordinary accuracy.', '原子钟能以极高的精度测量时间。', 'Atomic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solubility-1', 'solubility', 'The solubility of salt increases as the water becomes warmer.', '盐的溶解度随水温升高而增加。', 'solubility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dilute-1', 'dilute', 'Chemical waste is sometimes diluted with water before it is released.', '化学废物有时在排放前用水稀释。', 'diluted');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('evaporation-1', 'evaporation', 'Evaporation from the lake is highest during the hot summer months.', '湖水的蒸发量在炎热的夏季最高。', 'Evaporation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('condensation-1', 'condensation', 'Condensation forms on cold windows when warm air touches the glass.', '暖空气接触到冷玻璃时,窗户上就会产生冷凝水。', 'Condensation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distillation-1', 'distillation', 'Fresh water can be produced from seawater by distillation.', '淡水可以通过蒸馏从海水中制取。', 'distillation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dehydrate-1', 'dehydrate', 'Some desert animals can survive for weeks without water and rarely dehydrate.', '一些沙漠动物可以数周不喝水,也很少脱水。', 'dehydrate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decomposition-1', 'decomposition', 'Bacteria play a key role in the decomposition of dead plants.', '细菌在枯死植物的分解中起着关键作用。', 'decomposition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fusion-1', 'fusion', 'The Sun produces its energy through the fusion of hydrogen atoms.', '太阳通过氢原子聚变产生能量。', 'fusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('catalysis-1', 'catalysis', 'Catalysis is used in the production of most modern chemicals.', '大多数现代化学品的生产都要用到催化作用。', 'Catalysis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('polymer-1', 'polymer', 'Plastic is a polymer made up of long chains of smaller molecules.', '塑料是由较小分子形成的长链构成的聚合物。', 'polymer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hydrocarbon-1', 'hydrocarbon', 'Oil and natural gas are both types of hydrocarbon found underground.', '石油和天然气都是地下的碳氢化合物。', 'hydrocarbon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impurity-1', 'impurity', 'The filter removes almost every impurity from the drinking water.', '过滤器几乎能除去饮用水中的所有杂质。', 'impurity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neutralise-1', 'neutralise', 'Farmers add lime to neutralise the acid in their soil.', '农民加入石灰来中和土壤中的酸。', 'neutralise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corrode-1', 'corrode', 'Salt in the air can corrode metal structures near the sea.', '空气中的盐分会腐蚀海边的金属结构。', 'corrode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rot-1', 'rot', 'Wet conditions cause wooden buildings to rot within a few decades.', '潮湿的环境使木制建筑在几十年内腐烂。', 'rot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ignite-1', 'ignite', 'Dry leaves can easily ignite during the hot summer months.', '在炎热的夏季,干枯的树叶很容易点燃。', 'ignite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('explosive-1', 'explosive', 'The workers used explosives to cut the tunnel through the mountain.', '工人们用炸药在山中开凿隧道。', 'explosives');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('explosive-2', 'explosive', 'Coal dust in the air can be highly explosive in a mine.', '矿井中空气里的煤尘可能具有很强的爆炸性。', 'explosive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adhesive-1', 'adhesive', 'The insect produces a natural adhesive that holds its eggs to leaves.', '这种昆虫分泌一种天然粘合剂,把卵粘在叶子上。', 'adhesive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bleach-1', 'bleach', 'Bleach is sometimes used to remove the natural colour from paper.', '漂白剂有时被用来去除纸张的天然颜色。', 'Bleach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dye-1', 'dye', 'The ancient dye was made from a type of small sea snail.', '这种古老的染料是由一种小海螺制成的。', 'dye');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dye-2', 'dye', 'Local women dye the wool using plants collected from the hills.', '当地妇女用从山上采来的植物给羊毛染色。', 'dye');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foam-1', 'foam', 'The new type of foam keeps the inside of the building warm.', '这种新型泡沫能使建筑内部保持温暖。', 'foam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alchemy-1', 'alchemy', 'Alchemy was the early attempt to change ordinary metals into gold.', '炼金术是早期把普通金属变成黄金的尝试。', 'Alchemy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('zinc-1', 'zinc', 'Steel is often covered with a thin layer of zinc to prevent rust.', '钢常覆盖一层薄薄的锌来防锈。', 'zinc');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tin-1', 'tin', 'Tin was traded across the ancient world because it was needed for bronze.', '锡在古代世界各地都有贸易,因为制造青铜需要它。', 'Tin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nickel-1', 'nickel', 'Nickel is added to steel to make it stronger and harder.', '钢中加入镍可以使它更坚固、更硬。', 'Nickel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('platinum-1', 'platinum', 'Platinum is a rare metal used in car engines and jewellery.', '铂是一种稀有金属,用于汽车发动机和珠宝。', 'Platinum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('helium-1', 'helium', 'Helium is lighter than air and is often used in weather balloons.', '氦比空气轻,常用于气象气球。', 'Helium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ammonia-1', 'ammonia', 'Ammonia is widely used in the production of farm fertilisers.', '氨被广泛用于生产农业化肥。', 'Ammonia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('iodine-1', 'iodine', 'A lack of iodine in the diet can cause serious health problems.', '饮食中缺碘可能引起严重的健康问题。', 'iodine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('silicon-1', 'silicon', 'Most computer chips are made from silicon, which comes from sand.', '大多数计算机芯片由来自沙子的硅制成。', 'silicon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sulphur-1', 'sulphur', 'Burning coal releases sulphur, which can later fall as acid rain.', '燃煤释放硫,之后可能形成酸雨。', 'sulphur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brass-1', 'brass', 'Brass is a yellow metal made from a mixture of copper and zinc.', '黄铜是由铜和锌混合而成的黄色金属。', 'Brass');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bronze-1', 'bronze', 'People began to use bronze tools about five thousand years ago.', '人们大约在五千年前开始使用青铜工具。', 'bronze');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gasoline-1', 'gasoline', 'Electric cars are cheaper to run than cars powered by gasoline.', '电动汽车的运行成本比汽油车低。', 'gasoline');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('centigrade-1', 'centigrade', 'Water freezes at zero degrees centigrade and boils at one hundred.', '水在零摄氏度结冰,在一百摄氏度沸腾。', 'centigrade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artificial-1', 'artificial', 'Artificial lighting allowed factories to continue working through the night.', '人造照明让工厂能够彻夜运转。', 'Artificial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brittle-1', 'brittle', 'Glass is hard but brittle, so it breaks easily when dropped.', '玻璃坚硬但易碎,所以掉在地上很容易破。', 'brittle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('elasticity-1', 'elasticity', 'Skin loses some of its elasticity as people get older.', '随着年龄增长,皮肤会失去部分弹性。', 'elasticity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attrition-1', 'attrition', 'Rocks in the river become smooth through attrition over long periods.', '河里的石头经过长期磨损变得光滑。', 'attrition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vibration-1', 'vibration', 'Sensors can detect the slightest vibration in the walls of the bridge.', '传感器能检测到桥壁最轻微的振动。', 'vibration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('echo-1', 'echo', 'Bats find their food by listening to the echo of their own calls.', '蝙蝠通过倾听自己叫声的回声来寻找食物。', 'echo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acoustic-1', 'acoustic', 'The acoustic qualities of the hall make it ideal for concerts.', '这个大厅的声学效果使它非常适合举办音乐会。', 'acoustic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ultrasonic-1', 'ultrasonic', 'Dolphins communicate using ultrasonic sounds that humans cannot hear.', '海豚用人类听不到的超声波交流。', 'ultrasonic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mechanics-1', 'mechanics', 'The laws of mechanics explain how forces affect moving objects.', '力学定律解释了力如何影响运动的物体。', 'mechanics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dynamics-1', 'dynamics', 'Researchers study the dynamics of the group to see how leaders emerge.', '研究者研究群体的动态,观察领导者是如何产生的。', 'dynamics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thermodynamics-1', 'thermodynamics', 'The laws of thermodynamics describe how heat moves between objects.', '热力学定律描述了热量如何在物体之间传递。', 'thermodynamics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gravitation-1', 'gravitation', 'Newton''s law of gravitation explains the movement of the planets.', '牛顿的万有引力定律解释了行星的运动。', 'gravitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relativity-1', 'relativity', 'Einstein''s theory of relativity changed our understanding of space and time.', '爱因斯坦的相对论改变了我们对空间和时间的理解。', 'relativity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('magnetism-1', 'magnetism', 'Early sailors used magnetism to find their direction at sea.', '早期的水手利用磁性在海上辨别方向。', 'magnetism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electromagnetism-1', 'electromagnetism', 'Electromagnetism explains how electric motors turn electricity into movement.', '电磁学解释了电动机如何把电转化为运动。', 'Electromagnetism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electronics-1', 'electronics', 'Advances in electronics have made phones smaller and more powerful.', '电子学的进步使手机更小、功能更强大。', 'electronics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('semiconductor-1', 'semiconductor', 'Every modern computer depends on the semiconductor chips inside it.', '每台现代计算机都依赖其内部的半导体芯片。', 'semiconductor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transistor-1', 'transistor', 'The transistor made it possible to build much smaller radios.', '晶体管使制造小得多的收音机成为可能。', 'transistor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amplifier-1', 'amplifier', 'An amplifier makes weak signals from the microphone much stronger.', '放大器把麦克风发出的微弱信号大大增强。', 'amplifier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('insulator-1', 'insulator', 'Rubber is a good insulator and is used to cover electrical wires.', '橡胶是良好的绝缘体,被用来包裹电线。', 'insulator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('optics-1', 'optics', 'Advances in optics led to the development of better microscopes.', '光学的进步促成了更好的显微镜的发明。', 'optics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ray-1', 'ray', 'A ray of light bends as it passes from air into water.', '一束光从空气进入水中时会发生弯曲。', 'ray');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('translucent-1', 'translucent', 'The insect''s translucent wings allow some light to pass through.', '这种昆虫半透明的翅膀能让部分光线透过。', 'translucent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('opaque-1', 'opaque', 'The water became opaque because of the mud carried by the river.', '由于河水带来的泥沙,水变得不透明了。', 'opaque');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diffract-1', 'diffract', 'Waves diffract as they pass through a narrow opening in a sea wall.', '波浪穿过海堤的狭窄开口时会发生衍射。', 'diffract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('powder-1', 'powder', 'The rock is crushed into a fine powder and mixed with water.', '岩石被碾成细粉,然后与水混合。', 'powder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intensity-1', 'intensity', 'The intensity of the storm surprised even the weather forecasters.', '这场风暴的强度甚至让天气预报员都感到意外。', 'intensity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crystal-1', 'crystal', 'Salt forms small crystals as the water around it evaporates.', '周围的水蒸发时,盐形成小晶体。', 'crystals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fluid-1', 'fluid', 'The fluid inside the inner ear helps people to keep their balance.', '内耳中的液体帮助人们保持平衡。', 'fluid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equilibrium-1', 'equilibrium', 'The lake reached an equilibrium between the water flowing in and out.', '流入和流出的水量使湖泊达到了平衡。', 'equilibrium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bubble-1', 'bubble', 'Tiny bubbles of air trapped in the ice show what the ancient atmosphere was like.', '困在冰中的微小气泡显示了古代大气的样子。', 'bubbles');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crude-1', 'crude', 'Crude oil must be refined before it can be used as fuel.', '原油必须经过提炼才能用作燃料。', 'Crude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crude-2', 'crude', 'Early astronomers could make only crude estimates of the distance to the Moon.', '早期的天文学家只能粗略估算到月球的距离。', 'crude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dioxide-1', 'dioxide', 'Sulphur dioxide from factories was a major cause of acid rain.', '工厂排放的二氧化硫是酸雨的主要成因。', 'dioxide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swell-1', 'swell', 'Wood tends to swell when it becomes wet, so doors may stick.', '木头受潮后容易膨胀,所以门可能卡住。', 'swell');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('static-1', 'static', 'The figures remained static for ten years before beginning to rise.', '这些数字十年间保持不变,之后才开始上升。', 'static');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('static-2', 'static', 'Rubbing a balloon on your hair produces static electricity.', '用气球摩擦头发会产生静电。', 'static');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('synthesis-1', 'synthesis', 'The synthesis of new materials has become an important area of research.', '新材料的合成已成为一个重要的研究领域。', 'synthesis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('residue-1', 'residue', 'Pesticides can leave a harmful residue on fruit and vegetables.', '农药可能在水果和蔬菜上留下有害残留物。', 'residue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('absorption-1', 'absorption', 'Vitamin D helps with the absorption of calcium in the body.', '维生素 D 有助于人体吸收钙。', 'absorption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thickness-1', 'thickness', 'The thickness of the ice is measured by satellites each year.', '每年都用卫星测量冰的厚度。', 'thickness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('synthetic-1', 'synthetic', 'Synthetic fibres such as nylon are made from chemicals found in oil.', '尼龙等合成纤维由石油中的化学物质制成。', 'Synthetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('residual-1', 'residual', 'Residual heat in the ground warms the plants through the night.', '地面的余热整夜为植物保温。', 'Residual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flux-1', 'flux', 'The language is in a state of constant flux as new words appear.', '随着新词的出现,这种语言不断变化。', 'flux');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chloride-1', 'chloride', 'Sodium chloride is the chemical name for common salt.', '氯化钠是食盐的化学名称。', 'chloride');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('potassium-1', 'potassium', 'Bananas are a good source of potassium, which is important for the heart.', '香蕉是钾的良好来源,而钾对心脏很重要。', 'potassium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amplitude-1', 'amplitude', 'The amplitude of a sound wave determines how loud the sound is.', '声波的振幅决定声音的大小。', 'amplitude');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diffusion-1', 'diffusion', 'Gases spread through a room by the process of diffusion.', '气体通过扩散过程充满房间。', 'diffusion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('soluble-1', 'soluble', 'Sugar is soluble in water, but sand is not.', '糖可溶于水,但沙子不能。', 'soluble');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acidic-1', 'acidic', 'Water in the lake became more acidic after years of pollution.', '多年污染后,湖水变得更加酸性。', 'acidic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oscillation-1', 'oscillation', 'The regular oscillation of a pendulum was once used to keep time.', '钟摆有规律的摆动曾被用来计时。', 'oscillation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deflection-1', 'deflection', 'The deflection of light by gravity was first measured in 1919.', '引力使光线偏转的现象于 1919 年首次被测量到。', 'deflection');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oxidise-1', 'oxidise', 'Iron will oxidise quickly if it is left in wet conditions.', '铁放在潮湿环境中会很快氧化。', 'oxidise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cyclic-1', 'cyclic', 'The climate has gone through cyclic changes over thousands of years.', '数千年来,气候经历了周期性的变化。', 'cyclic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('steam-1', 'steam', 'Early railways used steam to power their engines.', '早期的铁路用蒸汽为发动机提供动力。', 'steam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flame-1', 'flame', 'The colour of the flame shows how hot the fire is.', '火焰的颜色显示出火有多热。', 'flame');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spark-1', 'spark', 'A single spark from a train set the dry grass on fire.', '火车上的一个火星点燃了干草。', 'spark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spark-2', 'spark', 'The court''s decision could spark a wider debate about water rights.', '法院的裁决可能引发一场关于水权的更广泛讨论。', 'spark');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vessel-1', 'vessel', 'The liquid is heated in a sealed vessel to keep it pure.', '液体在密封容器中加热,以保持纯净。', 'vessel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vessel-2', 'vessel', 'Fishing vessels from several countries operate in these waters.', '来自几个国家的渔船在这片海域作业。', 'vessels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vessel-3', 'vessel', 'Regular exercise helps to keep the blood vessels healthy.', '经常锻炼有助于保持血管健康。', 'vessels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wax-1', 'wax', 'Bees make wax to build the small cells in their hives.', '蜜蜂分泌蜡来建造蜂巢里的小巢室。', 'wax');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cement-1', 'cement', 'Producing cement releases a large amount of carbon dioxide into the air.', '生产水泥向空气中释放大量二氧化碳。', 'cement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('explode-1', 'explode', 'A build-up of gas may cause old mines to explode.', '气体积聚可能导致旧矿井爆炸。', 'explode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astronomy-1', 'astronomy', 'Ancient farmers used astronomy to work out when to plant their crops.', '古代农民利用天文学确定何时播种。', 'astronomy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astronomer-1', 'astronomer', 'The astronomer spent years recording the movement of the planets.', '这位天文学家花了多年时间记录行星的运动。', 'astronomer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('universe-1', 'universe', 'Scientists estimate that the universe is almost fourteen billion years old.', '科学家估计宇宙的年龄约为一百四十亿年。', 'universe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cosmos-1', 'cosmos', 'Early philosophers believed that the Earth was the centre of the cosmos.', '早期哲学家认为地球是宇宙的中心。', 'cosmos');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('galaxy-1', 'galaxy', 'Our galaxy contains billions of stars similar to the Sun.', '我们的星系包含数十亿颗与太阳相似的恒星。', 'galaxy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('the-milky-way-1', 'the-milky-way', 'The Milky Way can be seen clearly from areas with no city lights.', '在没有城市灯光的地区,银河系清晰可见。', 'The Milky Way');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solar-system-1', 'solar-system', 'Jupiter is the largest planet in the solar system.', '木星是太阳系中最大的行星。', 'solar system');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('planet-1', 'planet', 'Scientists have found thousands of planets orbiting other stars.', '科学家已经发现了数千颗围绕其他恒星运行的行星。', 'planets');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('satellite-1', 'satellite', 'The satellite sends back detailed images of the Earth''s surface.', '这颗卫星传回地球表面的详细图像。', 'satellite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orbit-1', 'orbit', 'The new telescope was placed in orbit high above the Earth.', '新望远镜被送入地球上空的高轨道。', 'orbit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orbit-2', 'orbit', 'The Earth takes about 365 days to orbit the Sun.', '地球绕太阳运行一周大约需要 365 天。', 'orbit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comet-1', 'comet', 'A bright comet was recorded by Chinese astronomers more than two thousand years ago.', '中国天文学家在两千多年前记录了一颗明亮的彗星。', 'comet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('asteroid-1', 'asteroid', 'Many scientists think an asteroid helped to wipe out the dinosaurs.', '许多科学家认为小行星促成了恐龙的灭绝。', 'asteroid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meteor-1', 'meteor', 'A meteor burns up as it enters the atmosphere at high speed.', '流星高速进入大气层时会燃烧殆尽。', 'meteor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meteorite-1', 'meteorite', 'The meteorite that landed in the desert contained small amounts of rare metals.', '落在沙漠中的陨石含有少量稀有金属。', 'meteorite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constellation-1', 'constellation', 'Sailors used the constellation in the northern sky to find their way.', '水手利用北方天空中的星座辨别方向。', 'constellation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nebula-1', 'nebula', 'New stars are formed in a nebula, a huge cloud of gas and dust.', '新恒星在星云中形成,星云是由气体和尘埃组成的巨大云团。', 'nebula');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('black-hole-1', 'black-hole', 'Nothing can escape from a black hole, not even light.', '任何东西都无法逃脱黑洞,甚至光也不行。', 'black hole');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supernova-1', 'supernova', 'A supernova occurs when a very large star explodes at the end of its life.', '当一颗非常大的恒星在生命末期爆炸时,就形成了超新星。', 'supernova');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('light-year-1', 'light-year', 'The nearest star to the Sun is just over four light-years away.', '距太阳最近的恒星只有四光年多。', 'light-years');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gravity-1', 'gravity', 'Gravity keeps the planets moving in their paths around the Sun.', '重力使行星沿轨道绕太阳运行。', 'Gravity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gravitational-1', 'gravitational', 'The Moon''s gravitational pull is the main cause of the tides.', '月球的引力是潮汐的主要成因。', 'gravitational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('telescope-1', 'telescope', 'With his telescope, Galileo discovered four moons around Jupiter.', '伽利略用望远镜发现了木星的四颗卫星。', 'telescope');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('observatory-1', 'observatory', 'The new observatory was built on a high mountain with clear skies.', '新天文台建在一座晴空万里的高山上。', 'observatory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spacecraft-1', 'spacecraft', 'The spacecraft travelled for seven years before reaching the planet.', '这艘航天器飞行了七年才到达这颗行星。', 'spacecraft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('probe-1', 'probe', 'The space probe sent back the first close-up pictures of the planet.', '这个太空探测器传回了这颗行星的第一批近距离照片。', 'probe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('probe-2', 'probe', 'Researchers used sound waves to probe the structure of the ocean floor.', '研究者用声波探查海底的结构。', 'probe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astronaut-1', 'astronaut', 'Living in space causes an astronaut''s bones and muscles to weaken.', '在太空生活使宇航员的骨骼和肌肉变弱。', 'astronaut');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('space-station-1', 'space-station', 'Scientists on the space station carry out experiments in very low gravity.', '空间站上的科学家在极低重力下进行实验。', 'space station');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lunar-1', 'lunar', 'Lunar rocks brought back to Earth have helped scientists understand its history.', '带回地球的月球岩石帮助科学家了解它的历史。', 'Lunar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('solar-1', 'solar', 'Solar energy now provides power to many remote villages.', '太阳能现在为许多偏远村庄提供电力。', 'Solar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eclipse-1', 'eclipse', 'Early people were often frightened by a sudden eclipse of the Sun.', '早期的人们常常被突如其来的日食吓坏。', 'eclipse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mars-1', 'mars', 'Water once flowed across the surface of Mars, according to recent studies.', '最近的研究表明,火星表面曾有水流动。', 'Mars');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('jupiter-1', 'jupiter', 'Jupiter has a huge storm that has lasted for hundreds of years.', '木星上有一场持续了数百年的巨大风暴。', 'Jupiter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('venus-1', 'venus', 'Thick clouds trap heat on Venus, making it the hottest planet.', '厚厚的云层把热量困在金星上,使它成为最热的行星。', 'Venus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astronomical-1', 'astronomical', 'The Mayans kept detailed astronomical records of the movements of the stars.', '玛雅人保留了详细的恒星运行天文记录。', 'astronomical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astronomical-2', 'astronomical', 'The cost of the project rose to an astronomical figure.', '这个项目的费用升到了天文数字。', 'astronomical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('celestial-1', 'celestial', 'Ancient navigators used celestial objects such as stars to find their position.', '古代航海者利用恒星等天体确定自己的位置。', 'celestial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cosmic-1', 'cosmic', 'Cosmic rays from deep space constantly strike the Earth''s atmosphere.', '来自深空的宇宙射线不断撞击地球大气层。', 'Cosmic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cosmology-1', 'cosmology', 'Modern cosmology tries to explain how the universe began.', '现代宇宙学试图解释宇宙是如何起源的。', 'cosmology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astrophysics-1', 'astrophysics', 'She studied astrophysics in order to understand how stars are formed.', '她学习天体物理学,以了解恒星是如何形成的。', 'astrophysics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('astrology-1', 'astrology', 'Unlike astronomy, astrology has no scientific basis at all.', '与天文学不同,占星术完全没有科学依据。', 'astrology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pseudoscience-1', 'pseudoscience', 'Scientists dismissed the claims about crystal healing as pseudoscience.', '科学家把水晶疗法的说法斥为伪科学。', 'pseudoscience');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quasar-1', 'quasar', 'A quasar can shine far more brightly than an entire galaxy.', '类星体的亮度可能远远超过整个星系。', 'quasar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dwarf-1', 'dwarf', 'The Sun will eventually become a small white dwarf.', '太阳最终将变成一颗小白矮星。', 'dwarf');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dwarf-2', 'dwarf', 'Dwarf trees grow near the top of the mountain, where it is colder.', '矮小的树生长在接近山顶、气温更低的地方。', 'Dwarf');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corona-1', 'corona', 'The Sun''s corona can be seen clearly during a total eclipse.', '日全食时可以清楚地看到太阳的日冕。', 'corona');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interstellar-1', 'interstellar', 'Interstellar travel is still far beyond our present technology.', '星际旅行仍然远远超出我们目前的技术水平。', 'Interstellar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interplanetary-1', 'interplanetary', 'Interplanetary missions take years of planning and huge amounts of money.', '行星际任务需要多年规划和巨额资金。', 'Interplanetary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intergalactic-1', 'intergalactic', 'Intergalactic distances are so huge that they are hard to imagine.', '星系际距离如此巨大,很难想象。', 'Intergalactic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revolve-1', 'revolve', 'The planets revolve around the Sun in almost circular paths.', '行星以近乎圆形的轨道绕太阳公转。', 'revolve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spaceship-1', 'spaceship', 'Living on a spaceship for years would be a great challenge for humans.', '在宇宙飞船上生活多年对人类来说是巨大的挑战。', 'spaceship');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mercury-1', 'mercury', 'Mercury is the smallest planet and the one closest to the Sun.', '水星是最小的行星,也是离太阳最近的行星。', 'Mercury');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('saturn-1', 'saturn', 'Saturn is famous for the bright rings of ice and rock around it.', '土星以环绕它的明亮冰岩环闻名。', 'Saturn');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('uranus-1', 'uranus', 'Uranus was first identified as a planet by William Herschel in 1781.', '1781 年,威廉·赫歇尔首次确认天王星是一颗行星。', 'Uranus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neptune-1', 'neptune', 'Neptune takes about 165 Earth years to travel around the Sun.', '海王星绕太阳运行一周大约需要 165 个地球年。', 'Neptune');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pluto-1', 'pluto', 'Pluto is no longer classed as a full planet by most astronomers.', '大多数天文学家不再把冥王星归为完整的行星。', 'Pluto');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('meteor-shower-1', 'meteor-shower', 'A meteor shower happens when the Earth passes through a trail of dust.', '地球穿过尘埃带时,就会出现流星雨。', 'meteor shower');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alien-1', 'alien', 'Alien plants brought in by ships can quickly replace local species.', '船只带来的外来植物可能迅速取代本地物种。', 'Alien');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alien-2', 'alien', 'Films about aliens reflect people''s interest in life on other planets.', '有关外星人的电影反映出人们对其他星球生命的兴趣。', 'aliens');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bang-1', 'bang', 'Most scientists think the universe began with a big bang.', '大多数科学家认为宇宙始于一场大爆炸。', 'bang');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rotation-1', 'rotation', 'The rotation of the Earth is the reason why we have day and night.', '地球的自转是昼夜交替的原因。', 'rotation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rotation-2', 'rotation', 'Crop rotation helps to keep the soil rich in nutrients.', '作物轮作有助于保持土壤养分充足。', 'rotation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rotate-1', 'rotate', 'The Moon rotates once in the time it takes to orbit the Earth.', '月球自转一周的时间与绕地球一周的时间相同。', 'rotates');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trajectory-1', 'trajectory', 'Scientists can calculate the exact trajectory of the asteroid.', '科学家能计算出这颗小行星的准确轨迹。', 'trajectory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mathematics-1', 'mathematics', 'Ancient Babylonians used advanced mathematics to predict the movement of planets.', '古巴比伦人运用高等数学预测行星的运动。', 'mathematics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arithmetic-1', 'arithmetic', 'Children first learn basic arithmetic by counting objects with their fingers.', '孩子们最初通过掰手指数东西来学习基本算术。', 'arithmetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('geometry-1', 'geometry', 'Egyptian builders used geometry to plan the shape of the pyramids.', '埃及建造者运用几何规划金字塔的形状。', 'geometry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calculus-1', 'calculus', 'Newton and Leibniz developed calculus at about the same time.', '牛顿和莱布尼茨几乎同时创立了微积分。', 'calculus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equation-1', 'equation', 'The equation allows us to calculate the energy released by the reaction.', '这个方程让我们能够计算反应释放的能量。', 'equation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('probability-1', 'probability', 'The probability of a major earthquake in the next decade is quite high.', '未来十年发生大地震的概率相当高。', 'probability');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('statistician-1', 'statistician', 'A statistician checked the data to make sure that the results were reliable.', '一位统计学家检查了数据,确保结果可靠。', 'statistician');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calculate-1', 'calculate', 'Early astronomers were able to calculate the size of the Earth.', '早期的天文学家能够计算出地球的大小。', 'calculate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('calculator-1', 'calculator', 'Pocket calculators became cheap and widely available in the 1970s.', '袖珍计算器在 20 世纪 70 年代变得便宜且普及。', 'calculators');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abacus-1', 'abacus', 'Traders in ancient China used an abacus to keep their accounts.', '古代中国的商人用算盘记账。', 'abacus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subtract-1', 'subtract', 'To find the difference, subtract the smaller number from the larger one.', '要求差值,就用较大的数减去较小的数。', 'subtract');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multiply-1', 'multiply', 'To find the area, multiply the length of the field by its width.', '要求面积,就用田地的长度乘以宽度。', 'multiply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multiply-2', 'multiply', 'Bacteria can multiply very quickly in warm food.', '细菌在温热的食物中能很快成倍增加。', 'multiply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('divide-1', 'divide', 'Divide the total distance by the time to calculate the average speed.', '用总距离除以时间可以算出平均速度。', 'Divide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('divide-2', 'divide', 'The mountains divide the country into two very different regions.', '山脉把这个国家分成两个截然不同的地区。', 'divide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decimal-1', 'decimal', 'The answer should be given to two decimal places.', '答案应保留两位小数。', 'decimal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('digit-1', 'digit', 'Telephone numbers in the country now have eleven digits.', '该国的电话号码现在有十一位数字。', 'digits');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('numeral-1', 'numeral', 'Roman numerals are still used on some clocks and old buildings.', '罗马数字仍用于一些时钟和老建筑上。', 'numerals');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('even-number-1', 'even-number', 'Any even number can be divided by two without a remainder.', '任何偶数都能被二整除。', 'even number');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('odd-number-1', 'odd-number', 'An odd number cannot be divided into two equal whole numbers.', '奇数不能被分成两个相等的整数。', 'odd number');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constant-1', 'constant', 'The speed of light in a vacuum is a physical constant.', '真空中的光速是一个物理常数。', 'constant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('constant-2', 'constant', 'The cave stays at a constant temperature throughout the entire year.', '这个洞穴全年保持恒定的温度。', 'constant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('function-1', 'function', 'Each function in the program performs one simple mathematical task.', '程序中的每个函数执行一项简单的数学任务。', 'function');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('function-2', 'function', 'The main function of the roots is to absorb water from the soil.', '根的主要功能是从土壤中吸收水分。', 'function');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('symmetry-1', 'symmetry', 'Most animals have a natural symmetry in the shape of their bodies.', '大多数动物的身体形状具有天然的对称性。', 'symmetry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parallel-1', 'parallel', 'The two rivers run parallel to each other for almost fifty kilometres.', '这两条河平行流淌了近五十公里。', 'parallel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parallel-2', 'parallel', 'There are clear parallels between the fall of Rome and modern events.', '罗马的衰落与现代事件之间有明显的相似之处。', 'parallels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intersect-1', 'intersect', 'The two roads intersect near the centre of the ancient town.', '这两条路在古镇中心附近相交。', 'intersect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vertical-1', 'vertical', 'The vertical axis of the graph shows the average temperature each month.', '图表的纵轴显示每月的平均气温。', 'vertical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('horizontal-1', 'horizontal', 'The rock layers are horizontal, showing that they have not been disturbed.', '岩层是水平的,说明它们没有受到扰动。', 'horizontal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plane-1', 'plane', 'Two lines on the same flat plane either cross or run side by side.', '同一平面上的两条线要么相交,要么平行。', 'plane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plane-2', 'plane', 'Thousands of commercial planes cross the Atlantic every day.', '每天有数千架商用飞机飞越大西洋。', 'planes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('segment-1', 'segment', 'The line segment connecting the two points is three centimetres long.', '连接两点的线段长三厘米。', 'segment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('segment-2', 'segment', 'Older people form a growing segment of the market for holidays.', '老年人在度假市场中所占的部分越来越大。', 'segment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('angle-1', 'angle', 'The light strikes the surface of the water at a narrow angle.', '光线以很小的角度照射到水面。', 'angle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obtuse-1', 'obtuse', 'An obtuse angle measures more than ninety degrees.', '钝角大于九十度。', 'obtuse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diameter-1', 'diameter', 'The trunk of the old tree measures more than three metres in diameter.', '这棵老树的树干直径超过三米。', 'diameter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radius-1', 'radius', 'Bears may hunt within a radius of fifty kilometres from their home.', '熊可能在距家半径五十公里的范围内捕猎。', 'radius');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circumference-1', 'circumference', 'An ancient Greek scholar made an early estimate of the circumference of the Earth.', '一位古希腊学者很早就估算出了地球的周长。', 'circumference');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rectangle-1', 'rectangle', 'The Roman town was laid out in the shape of a rectangle.', '这座罗马城镇布局呈长方形。', 'rectangle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('parallelogram-1', 'parallelogram', 'A parallelogram has two pairs of sides of equal length.', '平行四边形有两组等长的边。', 'parallelogram');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trapezoid-1', 'trapezoid', 'The field was shaped like a trapezoid, with one long side beside the river.', '这块田呈梯形,有一条长边靠着河。', 'trapezoid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('polygon-1', 'polygon', 'A polygon is a flat shape with three or more straight sides.', '多边形是有三条或更多直边的平面图形。', 'polygon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hexagonal-1', 'hexagonal', 'Bees build hexagonal cells because this shape uses the least wax.', '蜜蜂建造六边形的巢室,因为这种形状用蜡最少。', 'hexagonal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('octagonal-1', 'octagonal', 'The old tower has an unusual octagonal base made of local stone.', '这座古塔有一个不寻常的八边形基座,由当地石料砌成。', 'octagonal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('semicircle-1', 'semicircle', 'The seats in the ancient theatre were arranged in a semicircle.', '古代剧场的座位排成半圆形。', 'semicircle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ellipse-1', 'ellipse', 'Each planet moves around the Sun in the shape of an ellipse.', '每颗行星都沿椭圆轨迹绕太阳运行。', 'ellipse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cube-1', 'cube', 'Salt crystals naturally form in the shape of a tiny cube.', '盐的晶体天然呈微小的立方体。', 'cube');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sphere-1', 'sphere', 'The Earth is not a perfect sphere but is slightly flat at the poles.', '地球不是完美的球体,两极略扁。', 'sphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sphere-2', 'sphere', 'Women were largely excluded from the political sphere at that time.', '当时女性基本被排除在政治领域之外。', 'sphere');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cylinder-1', 'cylinder', 'The grain was stored in a tall metal cylinder beside the farm.', '谷物储存在农场旁一个高大的金属圆柱体中。', 'cylinder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cone-1', 'cone', 'Volcanoes often take the shape of a cone as lava builds up.', '随着熔岩堆积,火山常常形成圆锥形。', 'cone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spiral-1', 'spiral', 'The shell grows in a spiral as the animal inside gets bigger.', '随着里面的动物长大,贝壳呈螺旋状生长。', 'spiral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crescent-1', 'crescent', 'Viewed from Earth, the Moon appears as a thin crescent at this time.', '从地球上看,此时的月亮呈细细的新月形。', 'crescent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('matrix-1', 'matrix', 'The data was arranged in a matrix of rows and columns.', '数据被排列成由行和列组成的矩阵。', 'matrix');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('minus-1', 'minus', 'Temperatures at the research station can fall to minus sixty degrees.', '研究站的气温可能降到零下六十度。', 'minus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('linear-1', 'linear', 'The results show a linear relationship between age and body weight.', '结果显示年龄与体重之间存在线性关系。', 'linear');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spatial-1', 'spatial', 'Playing with building blocks helps children to develop spatial skills.', '玩积木有助于儿童发展空间能力。', 'spatial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('triangle-1', 'triangle', 'Early builders knew that the triangle is a very strong shape.', '早期的建造者知道三角形是非常坚固的形状。', 'triangle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('regression-1', 'regression', 'Researchers used regression to study the link between income and health.', '研究者使用回归方法研究收入与健康之间的关系。', 'regression');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vector-1', 'vector', 'A vector shows both the size and the direction of a force.', '向量同时表示力的大小和方向。', 'vector');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coefficient-1', 'coefficient', 'A high coefficient shows that the two variables are closely related.', '系数高表明这两个变量密切相关。', 'coefficient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infinite-1', 'infinite', 'Some philosophers believed that the universe was infinite in size.', '一些哲学家认为宇宙的大小是无限的。', 'infinite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('notation-1', 'notation', 'Modern mathematical notation makes calculations far easier than the older systems.', '现代数学符号让计算比旧系统简单得多。', 'notation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infinity-1', 'infinity', 'Ancient mathematicians struggled with the idea of infinity.', '古代数学家曾苦苦思索无穷大的概念。', 'infinity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subset-1', 'subset', 'The researchers studied a small subset of the full data.', '研究者研究了全部数据中的一小部分子集。', 'subset');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('computation-1', 'computation', 'Early computers could perform only a few simple computations each second.', '早期计算机每秒只能完成几次简单的计算。', 'computations');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('algebra-1', 'algebra', 'Algebra was developed further by Arab scholars during the Middle Ages.', '中世纪时,阿拉伯学者进一步发展了代数。', 'Algebra');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('non-linear-1', 'non-linear', 'Population growth often follows a non-linear pattern over long periods.', '长期来看,人口增长往往呈非线性模式。', 'non-linear');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('congruent-1', 'congruent', 'Two triangles are congruent if they have exactly the same shape and size.', '两个三角形如果形状和大小完全相同,就是全等的。', 'congruent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('axiom-1', 'axiom', 'Euclid began his work on geometry with a small number of axioms.', '欧几里得的几何学著作从少数几条公理开始。', 'axioms');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('factorial-1', 'factorial', 'The factorial of five is the product of all whole numbers up to five.', '五的阶乘是从一到五所有整数的乘积。', 'factorial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compute-1', 'compute', 'The machine could compute the positions of the planets accurately.', '这台机器能准确计算行星的位置。', 'compute');
